const a=JSON.parse('{"workId":"cai-gen-tan","chapter":{"id":"cai-gen-tan_ch-2","workId":"cai-gen-tan","order":2,"title":"應酬","difficulty":3,"estimatedMinutes":54,"passageIds":["cai-gen-tan_ch-2_p-1","cai-gen-tan_ch-2_p-2","cai-gen-tan_ch-2_p-3","cai-gen-tan_ch-2_p-4","cai-gen-tan_ch-2_p-5","cai-gen-tan_ch-2_p-6","cai-gen-tan_ch-2_p-7","cai-gen-tan_ch-2_p-8","cai-gen-tan_ch-2_p-9","cai-gen-tan_ch-2_p-10","cai-gen-tan_ch-2_p-11","cai-gen-tan_ch-2_p-12","cai-gen-tan_ch-2_p-13","cai-gen-tan_ch-2_p-14","cai-gen-tan_ch-2_p-15","cai-gen-tan_ch-2_p-16","cai-gen-tan_ch-2_p-17","cai-gen-tan_ch-2_p-18","cai-gen-tan_ch-2_p-19","cai-gen-tan_ch-2_p-20","cai-gen-tan_ch-2_p-21","cai-gen-tan_ch-2_p-22","cai-gen-tan_ch-2_p-23","cai-gen-tan_ch-2_p-24","cai-gen-tan_ch-2_p-25","cai-gen-tan_ch-2_p-26","cai-gen-tan_ch-2_p-27","cai-gen-tan_ch-2_p-28","cai-gen-tan_ch-2_p-29","cai-gen-tan_ch-2_p-30","cai-gen-tan_ch-2_p-31","cai-gen-tan_ch-2_p-32","cai-gen-tan_ch-2_p-33","cai-gen-tan_ch-2_p-34","cai-gen-tan_ch-2_p-35","cai-gen-tan_ch-2_p-36","cai-gen-tan_ch-2_p-37","cai-gen-tan_ch-2_p-38","cai-gen-tan_ch-2_p-39","cai-gen-tan_ch-2_p-40","cai-gen-tan_ch-2_p-41","cai-gen-tan_ch-2_p-42","cai-gen-tan_ch-2_p-43","cai-gen-tan_ch-2_p-44","cai-gen-tan_ch-2_p-45","cai-gen-tan_ch-2_p-46","cai-gen-tan_ch-2_p-47","cai-gen-tan_ch-2_p-48","cai-gen-tan_ch-2_p-49","cai-gen-tan_ch-2_p-50","cai-gen-tan_ch-2_p-51","cai-gen-tan_ch-2_p-52","cai-gen-tan_ch-2_p-53","cai-gen-tan_ch-2_p-54","cai-gen-tan_ch-2_p-55","cai-gen-tan_ch-2_p-56","cai-gen-tan_ch-2_p-57","cai-gen-tan_ch-2_p-58","cai-gen-tan_ch-2_p-59","cai-gen-tan_ch-2_p-60","cai-gen-tan_ch-2_p-61","cai-gen-tan_ch-2_p-62","cai-gen-tan_ch-2_p-63","cai-gen-tan_ch-2_p-64","cai-gen-tan_ch-2_p-65","cai-gen-tan_ch-2_p-66","cai-gen-tan_ch-2_p-67","cai-gen-tan_ch-2_p-68","cai-gen-tan_ch-2_p-69","cai-gen-tan_ch-2_p-70","cai-gen-tan_ch-2_p-71","cai-gen-tan_ch-2_p-72","cai-gen-tan_ch-2_p-73"],"tags":["文學","處世","應酬"]},"passages":[{"id":"cai-gen-tan_ch-2_p-1","chapterId":"cai-gen-tan_ch-2","order":1,"canonicalText":"先達笑彈冠，休向侯門輕曳裾；相知猶按劍，莫從世路暗投珠。","sentenceIds":["cai-gen-tan_ch-2_p-1_s-1","cai-gen-tan_ch-2_p-1_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"前輩賢達都會嘲笑那些急於謀求官職的人，所以不要輕易到達官顯貴門前搖尾乞憐；即便交情深厚的朋友有時也會手按寶劍相互猜忌，所以千萬不要在險惡的世路上輕易將自己的才華與真心明珠暗投。","analysis":"【主題與背景】本條告誡讀書人保持高尚的氣節與防範世俗的險惡。\\\\n【詞義與名物】前半句反對趨炎附勢，「先達笑彈冠」與「侯門輕曳裾」（典出鄒陽《獄中上樑王書》「曳裾王門」）指依附權貴是可恥的，應保持人格獨立；後半句「相知猶按劍」（典出《史記》「君子按劍相眄」）與「暗投珠」（明珠暗投）指出人心的複雜與世態的炎涼，即使是熟人也可能因誤解或利益而反目，因此在涉世中要懂得保護自己，不可將珍貴的抱負與真誠隨意暴露給不對的人。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-2","chapterId":"cai-gen-tan_ch-2","order":2,"canonicalText":"楊修之軀見殺於曹操，以露己之長也；韋誕之墓見伐於鐘繇，以祕己之美也。故哲士多匿採以韜光，至人常遜美而公善。","sentenceIds":["cai-gen-tan_ch-2_p-2_s-1","cai-gen-tan_ch-2_p-2_s-2","cai-gen-tan_ch-2_p-2_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"楊修之所以被曹操殺害，是因為他過分炫耀顯露自己的長處；韋誕的墳墓之所以被鐘繇盜掘，是因為他生前將珍貴的蔡邕筆法祕而不傳。所以，明智的人大多會隱匿光芒、韜光養晦，修養極高的至人則常把美德榮譽讓給他人，與大家共同分享善行。","analysis":"【主題與背景】本篇運用歷史典故（楊修因恃才傲物、露己之長而被曹操殺害；韋誕因珍藏蔡邕筆法祕而不宣，死後墓葬被鍾繇盜掘以求字帖），從正反兩面論證了「藏鋒」與「公善」的必要性。過度炫耀才華（露己之長）會招致殺身之禍；而自私地獨佔美好事物（祕己之美）也同樣會引來災難。\\\\n【詞義與名物】因此，智者主張「韜光養晦」，至人主張「遜美公善」（謙遜讓美，將善行公諸於世），這體現了道家不自見、不自彰、不自私的生存智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-3","chapterId":"cai-gen-tan_ch-2","order":3,"canonicalText":"少年的人，不患其不奮迅，常患畚迅而成鹵莽，故當抑其躁心；老成的人，不患其不持重，常患以持重而成退縮，故當振其惰氣。","sentenceIds":["cai-gen-tan_ch-2_p-3_s-1","cai-gen-tan_ch-2_p-3_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"年輕人，不擔心他們不夠奮發迅捷，通常擔心的是他們過於奮發迅捷而變得粗魯莽撞，因此應當壓制他們急躁的心氣；老練持重的人，不擔心他們不夠穩重，通常擔心的是他們因為過於穩重而變得退縮不前，因此應當振作他們懈怠的氣志。","analysis":"【訓詁與名物】\\\\n奮迅：精神振奮，行動迅速。鹵莽：粗野，草率，做事不謹慎，此處「畚迅」應為「奮迅」之誤。持重：謹慎穩重，不輕舉妄動。惰氣：懈怠消極的志氣。\\\\n【章法與結構】\\\\n本段採用對偶與對比的手法。「少年的人」對「老成的人」，「奮迅」對「持重」，「抑其躁心」對「振其惰氣」。句式整齊，上下兩聯形成鮮明的對照，既指出了不同年齡段與性格特徵的優缺點，又提出了針對性的修養方法。\\\\n【思想與義理】\\\\n本段蘊含著儒家「中庸」與道家「物極必反」的哲理。年輕人朝氣蓬勃但也容易流於急躁，老年人經驗豐富但也容易陷於保守退縮。因此，修身養性需要「對症下藥」，截長補短。對於過度外放的要加以收歛，對於過度收歛的要加以激發，使之達到過與不及之間的中道，從而達到身心與行事的平衡圓滿。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-4","chapterId":"cai-gen-tan_ch-2","order":4,"canonicalText":"望重縉紳，怎似寒微之頌德。朋來海宇，何如骨肉之孚心。","sentenceIds":["cai-gen-tan_ch-2_p-4_s-1","cai-gen-tan_ch-2_p-4_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在達官顯貴中享有崇高的聲望，哪裡比得上得到貧寒平民百姓的真誠頌德；朋友遍佈天下，哪裡比得上骨肉至親之間的心意相通與真誠信任。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈應酬〉第 77 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「望重縉紳怎似寒微之頌德朋來海宇何如骨肉之……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「望」、「重」、「縉」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-2_p-4）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-5","chapterId":"cai-gen-tan_ch-2","order":5,"canonicalText":"舌存常見齒亡，剛強終不勝柔弱；戶朽未聞樞蠹，偏執豈能及圓融。","sentenceIds":["cai-gen-tan_ch-2_p-5_s-1","cai-gen-tan_ch-2_p-5_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"舌頭依然存在，卻常常看到牙齒已經掉落，可見剛強的事物終究勝不過柔弱的事物；門板朽壞了，卻沒聽說門軸被蟲蛀壞，可見固執己見哪裡比得上靈活圓融。","analysis":"【訓詁與名物】\\\\n舌存常見齒亡：典出《說苑·敬慎》，老子之師常樅張開嘴巴讓老子看，問舌頭還在不在、牙齒還在不在，藉此說明柔弱勝剛強的道理。戶朽未聞樞蠹：門板雖然朽壞，但門軸因為經常轉動而不會被蟲蛀。樞，門軸。蠹，蛀蟲。偏執：固執己見，不知變通。圓融：靈活變通，圓滿融通。\\\\n【章法與結構】\\\\n本段為標準的駢偶句式。「舌存常見齒亡」對仗「戶朽未聞樞蠹」，「剛強終不勝柔弱」對仗「偏執豈能及圓融」。前一句藉由自然界與生活中的客觀物理現象作為譬喻，後一句則點出人事修養上的深刻道理，由物及人，說理透徹。\\\\n【思想與義理】\\\\n本段深刻體現了道家「柔弱勝剛強」與「流水不腐，戶樞不蠹」的哲學思想。牙齒雖硬但易折斷掉落，舌頭柔軟卻能長久留存，教導人應當放下剛愎自用與鋒芒畢露；門軸因為能順應開闔而常轉不息，故能免於敗壞，啟示人們在處世上應當保持心智的靈活與圓融，避免偏執一端。真正的強大不在於外表的剛硬，而在於內在的彈性與順應自然。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-6","chapterId":"cai-gen-tan_ch-2","order":6,"canonicalText":"物莫大於天地日月，而子美雲：「日月籠中鳥，乾坤水上萍。」事莫大於揖遜徵誅，而康節雲：「唐虞揖遜三杯酒，湯武徵誅一局棋。」人能以此胸襟眼界吞吐六合，上下千古，事來如漚生大海，事去如影滅長空，自經綸萬變而不動一塵矣。","sentenceIds":["cai-gen-tan_ch-2_p-6_s-1","cai-gen-tan_ch-2_p-6_s-2","cai-gen-tan_ch-2_p-6_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"萬物沒有比天地和日月更巨大的了，然而杜甫（子美）卻說：「日月如同籠中的鳥，乾坤就像水上的浮萍。」人間的事情沒有比禪讓與征討誅殺更重大的了，然而邵雍（康節）卻說：「唐堯虞舜的禪讓不過是三杯薄酒，商湯周武的征討誅殺不過是一局棋戲。」人如果能用這種胸襟和眼界來吞吐宇宙，俯仰千古，那麼事情到來時就像大海中產生的一朵泡沫，事情過去時就像晴空中消逝的一道影子，自然能經理規劃萬事萬變，而內心不染一粒塵埃。","analysis":"【主題與背景】本條融匯了儒、道、禪三家的超越境界。引用杜甫「日月籠中鳥，乾坤水上萍」（出自《衡州送李十一》）與邵雍（康節）「唐虞揖遜三杯酒，湯武徵誅一局棋」之語，意在破除空間與時間對人心靈的限制。\\\\n【詞義與名物】在宏大的宇宙觀（吞吐六合）與歷史觀（上下千古）下，世間萬事萬物均顯得渺小短暫。\\\\n【思想與篇章】文中以「漚生大海」和「影滅長空」為喻，體現了禪宗「無住」、「無留」的精神。人若具備此等胸襟，便能在面對世俗變局（經綸萬變）時，保持內心的安寧與定力，不為外物所動（不動一塵），展現了《菜根譚》儒道互補、出入自如的修養功夫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-7","chapterId":"cai-gen-tan_ch-2","order":7,"canonicalText":"君子好名，便起欺人之念；小人好名，猶懷畏人之心。故人而皆好名，則開詐善之門。使人而不好名，則絕為善之路。此譏好名者，當嚴責君子，不當過求於小人也。","sentenceIds":["cai-gen-tan_ch-2_p-7_s-1","cai-gen-tan_ch-2_p-7_s-2","cai-gen-tan_ch-2_p-7_s-3","cai-gen-tan_ch-2_p-7_s-4","cai-gen-tan_ch-2_p-7_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君子如果貪圖名譽，就會產生欺騙他人的念頭；小人如果貪圖名譽，還會懷有畏懼他人輿論的心思。因此，如果人人都貪圖名譽，就會開啟偽裝善良的大門；但假使人人都不圖名譽，又會斷絕人們行善的道路。這說明譏諷貪圖名譽的人，應當嚴厲苛責君子，而不應當過度要求小人。","analysis":"【主題與背景】本條對「好名」進行了辯證的剖析。君子本應內求諸己，若轉而好名，則易流於虛偽、欺世盜名（欺人之念），這是對儒家真誠人格的背叛，故需嚴責；而小人若能好名，至少還存有對輿論與法度的畏懼（畏人之心），能約束其惡行。\\\\n【詞義與名物】作者指出「好名」既有「開詐善之門」的流弊，又有「不絕為善之路」的社會教化功用（引導普通人行善）。\\\\n【思想與篇章】因此，在修養上應對居高位或自命君子者提出更高要求，反對虛偽的「偽君子」，而對普通人或小人則應寬容，利用其「好名」之心理引導其向善，體現了務實的社會倫理學觀點。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-8","chapterId":"cai-gen-tan_ch-2","order":8,"canonicalText":"大惡多從柔處伏，哲士須防綿裏之針；深仇常自愛中來，達人宜遠刀頭之蜜。","sentenceIds":["cai-gen-tan_ch-2_p-8_s-1","cai-gen-tan_ch-2_p-8_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"極大的邪惡往往隱藏在溫和柔順的表象下，有智慧的哲人必須防範棉花裡藏著的鋼針；深沉的仇恨常常是從極度的溺愛或親密中產生，通達事理的人應當遠離刀刃上塗抹的蜜糖。","analysis":"【主題與背景】本條警示世人防範隱蔽的危險，蘊含了道家「物極必反」與辯證法的智慧。以「綿裏之針」比喻柔順外表下的險惡，說明大奸大惡往往以恭順溫和的面目出現，需要極高的洞察力（哲士須防）。\\\\n【詞義與名物】以「刀頭之蜜」比喻過度親密或物慾誘惑背後隱藏的殺機，指出「愛極生恨」的心理規律。\\\\n【思想與篇章】達人宜保持適度的距離與清醒，不為眼前的甜蜜誘惑所惑。這與老子「柔弱勝剛強」的逆向應用相通，提醒涉世未深者在複雜的人際關係中保持警惕。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-9","chapterId":"cai-gen-tan_ch-2","order":9,"canonicalText":"持身涉世，不可隨境而遷。須是大火流金而清風穆然，嚴霜殺物而和氣藹然，陰霾翳空而慧日朗然，洪濤倒海而砥柱屹然，方是宇宙內的真人品。愛是萬緣之根，當知割捨。識是眾欲之本，要力掃除。","sentenceIds":["cai-gen-tan_ch-2_p-9_s-1","cai-gen-tan_ch-2_p-9_s-2","cai-gen-tan_ch-2_p-9_s-3","cai-gen-tan_ch-2_p-9_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"立身處世，絕不能隨著環境的變化而動搖。必須做到：即使在烈日熔化金屬般（大火流金）的逆境中，內心依然像清風般安詳莊重；在嚴霜摧殘萬物的肅殺氣氛中，待人依然像春風般和藹可親；在陰霾遮蔽天空的黑暗時刻，智慧的心燈依然如烈日般明亮；在波濤洶湧、翻江倒海的狂瀾中，操守依然像中流砥柱般屹立不動，這才是宇宙間真正的崇高品格。執著的愛欲是萬般因緣的根源，應當懂得割捨；世俗的知見與分別心是各種慾望的根本，必須努力掃除。","analysis":"【主題與背景】本條前半部分強調儒家在逆境中堅守操守的精神，後半部分引申出佛家破除執著、空掉知見的修行法門。作者以「大火流金」、「嚴霜殺物」、「陰霾翳空」、「洪濤倒海」比喻世間的種種逆境與考驗，要求君子保持「清風穆然」、「和氣藹然」、「慧日朗然」、「砥柱屹然」的定力與智慧，這是儒家「士志於道」和「不動心」的體現。\\\\n【詞義與名物】隨後指出「愛」（執著、情愛）與「識」（妄想分別心、世俗智巧）是痛苦與慾望的根源，需以佛家空宗的方法進行「割捨」與「掃除」，從而達到物我兩忘、隨緣不變的「真人品」境界。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-10","chapterId":"cai-gen-tan_ch-2","order":10,"canonicalText":"作人要脫俗，不可存一矯俗之心；應世要隨時，不可起一趨時之念。","sentenceIds":["cai-gen-tan_ch-2_p-10_s-1","cai-gen-tan_ch-2_p-10_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做人應當超凡脫俗，但絕不能存有故意違背世俗、標新立異的心思；應對世事應當順應時代的變化，但絕不能生出迎合時尚、趨炎附勢的念頭。","analysis":"【主題與背景】本條論述了「脫俗」與「應世」的中庸之道。作者反對為了脫俗而故意做作、刻意標榜（矯俗之心），因為「矯俗」本質上仍是對世俗的一種執著與抗拒，流於虛偽；真正的脫俗應是自然而然的超曠。\\\\n【詞義與名物】同理，「隨時」是指順應自然與時勢的客觀規律，而「趨時」則是出於功利目的去迎合潮流、阿諛奉承。\\\\n【思想與篇章】此論點繼承了孔子「君子和而不同」與孟子「可以仕則仕，可以止則止」的時中智慧，強調持身須中正平和，不落兩邊。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-11","chapterId":"cai-gen-tan_ch-2","order":11,"canonicalText":"寧有求全之毀，不可有過情之譽；寧有無妄之災，不可有非分之福。","sentenceIds":["cai-gen-tan_ch-2_p-11_s-1","cai-gen-tan_ch-2_p-11_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"寧可承受因他人求全責備而招致的毀謗，也不可接受超過實際情況的過度讚譽；寧可遭受意料之外的自然災禍，也不可享受不符合自己身份與功德的非分福祿。","analysis":"【主題與背景】本條探討了毀譽與禍福的修養態度。「求全之毀」指因他人期望過高或吹毛求疵而來的指責，這能促使自己反省修身；而「過情之譽」則容易讓人滋生驕傲與虛榮，甚至埋下日後身敗名裂的禍根。\\\\n【詞義與名物】「無妄之災」是天意或意外，雖受折磨但問心無愧；而「非分之福」則是德不配位、強求而得的福報，易招致災殃。\\\\n【思想與篇章】此思想源於《易經》「德薄而位尊，知小而謀大，力小而任重，鮮不及矣」的憂患意識，提倡安分守己、實事求是的處世原則。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-12","chapterId":"cai-gen-tan_ch-2","order":12,"canonicalText":"毀人者不美，而受人毀者遭一番訕謗便加一番修省，可釋回而增美；欺人者非福，而受人欺者遇一番橫逆便長一番器宇，可以轉禍而為福。","sentenceIds":["cai-gen-tan_ch-2_p-12_s-1","cai-gen-tan_ch-2_p-12_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"毀謗他人的人品德並不完美，但承受毀謗的人每遭遇一次誹謗，就增加一次自我反省與修養的機會，從而可以消除邪僻的心思而增加美德；欺騙他人的人不會得到福報，但承受欺騙的人每遇到一次蠻不講理的橫禍，就增長一分寬宏的度量與氣魄，從而能夠轉化災禍為福澤。","analysis":"【主題與背景】本條進一步發揮「逆境磨煉」的思想，教導人們如何將他人的惡行轉化為自我提升的契機。在《菜根譚》看來，外在的「訕謗」與「橫逆」雖是負面的，但如果受害者能以儒家的「反求諸己」（修省）和道禪的「寬宏度量」（長器宇）來對待，就能「釋回」（解釋消除邪僻、回歸正道）並「轉禍為福」。\\\\n【詞義與名物】這不僅是心理上的自我調適，更是一種高超的處世智慧，將人生的阻力轉化為成長的動力。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-13","chapterId":"cai-gen-tan_ch-2","order":13,"canonicalText":"夢裏懸金佩玉，事事逼真，睡去雖真覺後假；閒中演偈談元，言言酷似，說來雖是用時非。","sentenceIds":["cai-gen-tan_ch-2_p-13_s-1","cai-gen-tan_ch-2_p-13_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在夢境中身佩金印、腰懸美玉，一切情景都顯得無比真實，睡著時雖然覺得是真，醒來後才知道全是虛假；在閒暇時參演佛偈、清談玄理，字字句句都顯得極其相似，說起來雖然頭頭是道，但在真正面對考驗和實用時卻完全不是那麼回事。","analysis":"【主題與背景】本條主要諷刺口頭禪與虛妄的清談，強調實踐與真修實行的重要性。作者以「夢中懸金佩玉」的幻境，對比「閒中演偈談元」的空談。\\\\n【詞義與名物】這是在批判明代中後期流行的「狂禪」與空疏之風，當時許多士人僅在口頭上談論心性、搬弄禪機（言言酷似），卻缺乏真正克己復禮的實踐工夫。\\\\n【思想與篇章】一旦面臨生死、名利或道德抉擇（用時），這些空洞的理論便毫無用處（用時非）。這體現了《菜根譚》務實、知行合一的儒家實學精神。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-14","chapterId":"cai-gen-tan_ch-2","order":14,"canonicalText":"天欲禍人，必先以微福驕之，所以福來不必喜，要看他會受；天欲福人，必先以微禍儆之，所以禍來不必憂，要看他會救。","sentenceIds":["cai-gen-tan_ch-2_p-14_s-1","cai-gen-tan_ch-2_p-14_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"上天想要降下災禍給一個人，必定先用微小的福報來使他驕傲，所以福報到來時不值得過分高興，關鍵要看他是否懂得合理承受與珍惜；上天想要降下福澤給一個人，必定先用微小的災禍來警戒他，所以災禍到來時不必憂心忡忡，關鍵要看他是否懂得自我反省與挽救。","analysis":"【主題與背景】本條深刻闡述了禍福相依、天道忌盈的哲理。其思想根源於老子《道德經》「禍兮福之所倚，福兮禍之所伏」。\\\\n【詞義與名物】天道運行的規律往往以「微福」考驗人的心志，看其是否會因驕奢而招禍（會受）；以「微禍」磨礪人的意志，看其是否能因警惕、反省而化解危機（會救）。\\\\n【思想與篇章】這啟示我們在順境中要保持謙遜與警惕，在逆境中要保持樂觀與擔當，以主觀的修養來應對外在環境的吉凶變化。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-15","chapterId":"cai-gen-tan_ch-2","order":15,"canonicalText":"榮與辱共蒂，厭辱何須求榮；生與死同根，貪生不必畏死。","sentenceIds":["cai-gen-tan_ch-2_p-15_s-1","cai-gen-tan_ch-2_p-15_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"榮耀與屈辱是結在同一個蒂上的，既然討厭屈辱，又何必去強求榮耀呢？生存與死亡是生在同一個根上的，既然貪戀生存，也就不必去畏懼死亡。","analysis":"【訓詁與名物】\\\\n共蒂：並生於同一個果蒂，比喻兩者緊密相連，不可分割。蒂，花或瓜果跟枝莖相連的部分。同根：生長在同一個樹根上，指事物的本源相同。何須：何必，哪裡需要。\\\\n【章法與結構】\\\\n句子採用了對仗的句型。「榮與辱共蒂」對偶「生與死同根」，「厭辱何須求榮」對偶「貪生不必畏死」。結構上前半句先陳述事物一體兩面的客觀事實，後半句再推導出面對這兩極現象時應有的豁達態度，邏輯嚴密且富有節奏感。\\\\n【思想與義理】\\\\n這段話充滿了莊子「齊物」與「死生一如」的齊觀思想。世人往往好榮惡辱、貪生怕死，然而榮辱與生死其實是相對而相生的概念，沒有辱就沒有榮，有生就必然有死。它們是同一本體在不同階段或不同面向的顯現。如果我們能看透對立事物之間互相依存的本質，就能超越得失之患與生死之懼，達到內心真正的寧靜與解脫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-16","chapterId":"cai-gen-tan_ch-2","order":16,"canonicalText":"作人只是一味率真，蹤跡雖隱還顯；存心若有半毫未凈，事為雖公亦私。","sentenceIds":["cai-gen-tan_ch-2_p-16_s-1","cai-gen-tan_ch-2_p-16_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做人只要一味保持真誠坦率，即使隱居山野，其高尚的名聲與品德依然會顯揚於世；內心如果存有半點不乾淨的私慾，那麼做起事來即使名義上是出於公心，本質上也是自私的。","analysis":"【主題與背景】本條強調了做人的「真誠」與動機的「純潔」，屬於儒家「誠意正心」與宋代理學「存天理，滅人慾」的範疇。前半句指出「率真」是人格的核心，真誠的人不求名利，但德香自傳（隱還顯）。\\\\n【詞義與名物】後半句則強調居心（存心）的純粹性，若動機中夾雜著私心、虛名，即使表面上在做公益或公正的事（事為雖公），也是偽善和私利的延伸。\\\\n【思想與篇章】這要求修行者在最隱微的念頭上做克己工夫（慎獨）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-17","chapterId":"cai-gen-tan_ch-2","order":17,"canonicalText":"鷯佔一枝，反笑鵬心奢侈；兔營三窟，轉嗤鶴壘高危。智小者不可以謀大，趣卑者不可與談高。信然矣！","sentenceIds":["cai-gen-tan_ch-2_p-17_s-1","cai-gen-tan_ch-2_p-17_s-2","cai-gen-tan_ch-2_p-17_s-3","cai-gen-tan_ch-2_p-17_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鷦鷯只佔用樹林中的一根樹枝，反而譏笑大鵬鳥想要展翅飛越萬裡的雄心太過奢侈；兔子營造了三個藏身的巢穴，反而嗤笑仙鶴將巢築在高聳的樹梢上太過危險。智慧微小的人不可以與其共謀大事，志趣卑下的人不可以與其共談高遠的理想。這話確實是真的啊！","analysis":"【主題與背景】本條典故出自《莊子·逍遙遊》，如「鷦鷯巢於深林，不過一枝」以及大鵬與蜩、學鳩的對比。作者借鷦鷯笑鵬、狡兔嗤鶴的寓言，揭示了人與人之間在格局、視野和志向上的巨大差異。\\\\n【詞義與名物】眼界狹隘、安於現狀者（智小者、趣卑者），無法理解胸懷大志、追求高遠境界者的抱負。\\\\n【思想與篇章】因此，在涉世交友中，應懂得因材施教或尋找志同道合者，不可強求夏蟲語冰，展現了清醒的人際洞察力。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-18","chapterId":"cai-gen-tan_ch-2","order":18,"canonicalText":"貧賤驕人，雖涉虛憍，還有幾分俠氣；英雄欺世，縱似揮霍，全沒半點真心。糟糠不為彘肥，何事偏貪鈎下餌；錦綺豈因犧貴，誰人能解籠中囮。","sentenceIds":["cai-gen-tan_ch-2_p-18_s-1","cai-gen-tan_ch-2_p-18_s-2","cai-gen-tan_ch-2_p-18_s-3","cai-gen-tan_ch-2_p-18_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"貧賤的人在富貴者面前表現出傲慢（貧賤驕人），雖然不免有些虛張聲勢的驕狂，但也還保有幾分不甘屈服的俠義骨氣；世俗的英雄玩弄權術、欺騙世人，縱然表面上表現得豪爽揮霍，卻全無半點真誠之心。粗劣的酒糟糠秕本不是為了把豬餵肥，人又何必偏偏去貪圖魚鉤下的誘餌呢？華麗的錦繡絲綢難道是因為牛羊要當祭品才顯得高貴，又有誰能理解籠子裡作為誘餌的小鳥的悲哀呢？","analysis":"【主題與背景】本條批判了虛偽的世俗英雄，並以生動的比喻規勸人們遠離名利誘惑。「貧賤驕人」出自《史記·魏世家》，雖屬傲慢，卻代表了對強權的不屈；而「英雄欺世」則是政客、投機者的功利手段，毫無誠意。\\\\n【詞義與名物】後半部分運用多重譬喻：「糟糠」與「彘肥」說明不要為了微薄利益而甘受宰割，莫貪「鉤下餌」；「錦綺」與「犧貴」典出《莊子》，祭祀用的牛（犧牛）雖披錦繡，卻難逃被宰殺的命運，指代依附權貴的榮華富貴；「籠中囮」（囮，音ㄜˊ，誘鳥）比喻為了名利失去自由並陷害同類的人。\\\\n【思想與篇章】全篇旨在告誡人們保持獨立人格，切勿為名利所羈絆。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-19","chapterId":"cai-gen-tan_ch-2","order":19,"canonicalText":"琴書詩畫，達士以之養性靈，而庸夫徒賞其跡像；山川雲物，高人以之助學識，而俗子徒玩其光華。可見事物無定品，隨人識見以為高下。故讀書窮理，要以識趣為先。","sentenceIds":["cai-gen-tan_ch-2_p-19_s-1","cai-gen-tan_ch-2_p-19_s-2","cai-gen-tan_ch-2_p-19_s-3","cai-gen-tan_ch-2_p-19_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"彈琴、讀書、吟詩、作畫，通達的人用它們來陶冶性情、涵養心靈，而平庸的人卻僅僅欣賞它們表面的形式與痕跡；山川、雲彩、草木等自然景物，高尚的人用它們來輔助自己的學問與見識，而世俗的人卻只管賞玩日常景物表面的光彩。可見世間的事物並沒有固定不變的品位，而是隨著人們眼光與見識的高低而區分出高下。所以，讀書探究萬物的道理，應當把培養高雅的眼識與志趣放在第一位。","analysis":"【主題與背景】本條論述了藝術、自然與心靈的關係，強調「識趣」（眼識與志趣）在讀書窮理中的核心地位。同樣的琴書詩畫與山川風物，在「達士」、「高人」眼中是性靈的寄託和智慧的源泉，而在「庸夫」、「俗子」眼中只是玩物和表面的感官刺激（跡像、光華）。\\\\n【詞義與名物】這說明外物本身的價值取決於主體心境的層次（事物無定品，隨人識見以為高下）。\\\\n【思想與篇章】這與禪宗「心生則種種法生」及儒家注重心性修養的理念高度一致。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-20","chapterId":"cai-gen-tan_ch-2","order":20,"canonicalText":"美女不尚鉛華，似疏梅之映淡月；禪師不落空寂，若碧沼之吐青蓮。","sentenceIds":["cai-gen-tan_ch-2_p-20_s-1","cai-gen-tan_ch-2_p-20_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"美麗的女子不崇尚濃妝豔抹，就像稀疏的梅花映襯著清淡的月光般高雅；修行的禪師不墮入虛無死寂，就像清澈的碧綠池沼中挺立著一朵青蓮般生機盎然。","analysis":"【主題與背景】本條以極具美感的對偶句，闡述了「自然本真」與「真空妙有」的修行境界。前半句「美女不尚鉛華」比喻天然去雕飾的美，如同疏梅淡月，代表了道家崇尚自然、反對虛飾的美學。\\\\n【詞義與名物】後半句「禪師不落空寂」則是對小乘佛教偏空、死守空寂的糾偏。\\\\n【思想與篇章】大乘禪宗主張「即色即空」、「在欲行禪」，如同碧沼中吐出的青蓮，雖出污泥而不染，且充滿活潑的生命力（生機）。兩者共同指向了一種不偏不倚、圓融中和的生命藝術。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-21","chapterId":"cai-gen-tan_ch-2","order":21,"canonicalText":"廉官多無後，以其太清也；癡人每多福，以其近厚也。故君子雖重廉介，不可無含垢納污之雅量。雖戒癡頑，亦不必有察淵洗垢之精明。","sentenceIds":["cai-gen-tan_ch-2_p-21_s-1","cai-gen-tan_ch-2_p-21_s-2","cai-gen-tan_ch-2_p-21_s-3","cai-gen-tan_ch-2_p-21_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"清廉的官吏大多沒有後代，是因為他們潔身自好到了水至清則無魚的地步；愚笨木訥的人往往很有福氣，是因為他們的性格接近於樸實溫厚。所以，君子雖然器重廉潔正直的操守，但也絕不能缺乏包容缺點、容納汙垢的寬宏雅量；雖然要防範愚蠢與頑固，但也完全不必擁有察看深淵之魚、清洗他人汙垢那般過分苛刻的精明。","analysis":"【主題與背景】本條體現了《菜根譚》融合儒道、提倡「中庸包容」與「大智若愚」的智慧。老子說「大直若屈，大巧若拙」，古語亦云「水至清則無魚，人至察則無徒」。\\\\n【詞義與名物】「廉官無後」與「癡人多福」是民間的直觀觀察，作者藉此說明過分追求極致的清白（太清）會失去孕育萬物的溫和之氣；而溫厚、看似愚笨（近厚）卻能聚福。\\\\n【思想與篇章】君子應具備「含垢納污」的雅量，避免「察淵」（《韓非子》「察見淵魚者不祥」）式的過度精明，以求得人際的和諧與內心的寬廣。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-22","chapterId":"cai-gen-tan_ch-2","order":22,"canonicalText":"密則神氣拘逼，疏則天真爛漫，此豈獨詩文之工拙從此分哉！吾見周密之人純用機巧，疏狂之士獨任性真，人心之生死亦於此判也。","sentenceIds":["cai-gen-tan_ch-2_p-22_s-1","cai-gen-tan_ch-2_p-22_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"嚴密拘謹就會使精神和氣勢顯得窘迫逼仄，寬疏自然就會顯得天真爛漫，難道僅僅是詩文的巧妙與拙劣從這裡劃分嗎？我看那些心思過於周密的人純粹是在使用心機巧詐，而疏曠狂放的雅士則獨自放任天性真誠，人心的生氣與死寂，也是從這裡判別出來的啊。","analysis":"【主題與背景】本條將文論（詩文的「密」與「疏」）引入人生修養論，提倡疏曠、真率，反對心機周密。作者認為，藝術創作中的「疏」能帶來天真爛漫的生命力，同樣地，在為人處世上，過分周密防範、處處算計的人（純用機巧），其心靈是乾枯無生氣的（死）；而性情疏狂、直率真誠的人（任性真），其心靈是活潑有生機的（生）。\\\\n【詞義與名物】這是一種反對儒家刻板禮法與心智巧詐、崇尚道家率真自然的態度。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-23","chapterId":"cai-gen-tan_ch-2","order":23,"canonicalText":"翠筱傲嚴霜，節縱孤高，無傷沖雅；紅蕖媚秋水，色雖艷麗，何損清修。","sentenceIds":["cai-gen-tan_ch-2_p-23_s-1","cai-gen-tan_ch-2_p-23_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"翠綠的竹子傲立於嚴霜之中，它的氣節縱然孤高，卻不損害它虛心淡雅的風度；紅色的荷花在秋水旁顯得嫵媚，它的色彩雖然豔麗，又何嘗損害它出淤泥而不染的清淨修持。","analysis":"【主題與背景】本條通過「翠筱」（竹）與「紅蕖」（荷花）這兩種植物的自然特性，闡述了君子「和而不同」、理事無礙的修養。「筱」象徵孤高之節，但竹心是空的，代表謙虛沖淡（無傷沖雅）；「蕖」雖紅豔嫵媚，但荷花根自清澈，代表在俗世中不失自性（何損清修）。\\\\n【詞義與名物】作者意在說明，真正的修行不流於偏執：高潔者不必刻意表現得冷酷孤傲，處繁華者亦能保持內心的純潔。\\\\n【思想與篇章】這是對人格完美和諧的追求。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-24","chapterId":"cai-gen-tan_ch-2","order":24,"canonicalText":"貧賤所難，不難在砥節，而難在用情；富貴所難，不難在推恩，而難在好禮。","sentenceIds":["cai-gen-tan_ch-2_p-24_s-1","cai-gen-tan_ch-2_p-24_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"處於貧賤境遇時最難做到的，不在於磨礪操守、堅持氣節，而在於待人接物時能保持溫厚真摯的情義；處於富貴境遇時最難做到的，不在於施捨恩惠、接濟他人，而在於能真誠地尊重他人、以禮相待。","analysis":"【主題與背景】本條對貧賤與富貴兩種境遇下的道德難題進行了極具洞察力的剖析。貧賤之人容易為了生存或因自尊心過強而變得偏激、冷酷或多疑，因此「砥節」（不移其志）相對容易，而保持溫和、不怨天尤人的「用情」（對家人或朋友溫柔真摯）卻極難。\\\\n【詞義與名物】富貴之人有能力施捨，故「推恩」（物質施予）較易，但要他們放下居高臨下的優越感，真正謙遜地「好禮」（尊重他人、以禮待人）卻非常難。\\\\n【思想與篇章】這體現了對人性的深刻體察，要求修身者在不易察覺的心理細節處下功夫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-25","chapterId":"cai-gen-tan_ch-2","order":25,"canonicalText":"簪纓之士，常不及孤寒之子可以抗節致忠；廟堂之士，常不及山野之夫可以料事燭理。何也？彼以濃艷損志，此以淡泊全真也。","sentenceIds":["cai-gen-tan_ch-2_p-25_s-1","cai-gen-tan_ch-2_p-25_s-2","cai-gen-tan_ch-2_p-25_s-3","cai-gen-tan_ch-2_p-25_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"達官顯貴（簪纓之士），往往比不上貧寒出身的子弟能夠堅守節操、盡忠報國；身居朝廷高位的政要（廟堂之士），往往比不上隱居山野的農夫野老能夠洞察事理、判斷局勢。這是為什麼呢？原因在於顯貴者被濃厚的名利富貴損害了志向，而貧寒山野者卻因為生活淡泊而保全了純真本性。","analysis":"【主題與背景】本條論述了「淡泊名利」對保全心志與智慧的重要性。簪纓與廟堂代表了世俗的權力與富貴，其生活環境充滿了物質誘惑與政治算計（濃艷），極易腐蝕人的意志（損志），使其在面對忠義抉擇時畏首畏尾，在判斷時局時被私利蒙蔽。\\\\n【詞義與名物】相反，孤寒與山野之人遠離名利場，生活簡單，因而能「全真」（保全純真本性與清明理智），所以在關鍵時刻反而能展現出更高的道德勇氣與更透徹的智慧。\\\\n【思想與篇章】這也是道家反璞歸真思想在社會政治學上的體現。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-26","chapterId":"cai-gen-tan_ch-2","order":26,"canonicalText":"榮寵傍邊辱等待，不必揚揚；困窮背後福跟隨，何須慼慼。","sentenceIds":["cai-gen-tan_ch-2_p-26_s-1","cai-gen-tan_ch-2_p-26_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"榮耀與寵信的旁邊，就有屈辱在等待著，因此得志時不必洋洋得意；困頓與窮苦的背後，就有福氣在跟隨著，因此失意時何必哀傷憂愁。","analysis":"【訓詁與名物】\\\\n榮寵：光榮與恩寵，指得到高官厚祿或被長官重用。揚揚：得意的樣子，如成語「得意洋洋」。困窮：艱難窘迫，無路可走。慼慼：憂愁哀傷的樣子，《論語》有「小人長慼慼」之語。\\\\n【章法與結構】\\\\n全文以工整的對偶句構成，「榮寵」與「困窮」相對，「傍邊」與「背後」相對，「辱等待」與「福跟隨」相對。句法上先描述順境與逆境潛藏的轉機，後接以「不必」與「何須」的反詰與勸告語氣，勸誡人們調整心態。\\\\n【思想與義理】\\\\n本段傳達了老子「禍兮福之所倚，福兮禍之所伏」的辯證哲學。世間的福禍榮辱並非絕對與永恆，而是在不斷地互相轉化。處於巔峯與順境時，往往潛伏著危機與衰敗的因子，故應當保持謙卑；處於低谷與逆境時，往往孕育著轉機與希望，故不應輕言放棄。這種超越眼下境遇、洞察事物發展規律的智慧，能夠幫助人們在人生起伏中保持恬淡與安詳。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-27","chapterId":"cai-gen-tan_ch-2","order":27,"canonicalText":"古人閑適處，今人卻忙過了一生；古人實受處，今人又虛度了一世。總是耽空逐妄，看個色身不破，認個法身不真耳。","sentenceIds":["cai-gen-tan_ch-2_p-27_s-1","cai-gen-tan_ch-2_p-27_s-2","cai-gen-tan_ch-2_p-27_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古人感到悠閒舒適的地方，現代人卻忙忙碌碌地度過了一生；古人獲得真實受用、安頓心靈的地方，現代人卻虛無縹緲地荒廢了一世。這都是因為世人沉溺於空無、追逐著虛妄，看不透這具肉體凡胎（色身）的幻滅，也體認不清那永恆的自性真面目（法身）啊。","analysis":"【主題與背景】本條採用佛教的「色身」與「法身」概念，對當時社會上「耽空逐妄」、汲汲營營的風氣進行了深刻的批判。古人重內在的生命體驗與精神閒適，故能「實受」；今人重外在的名利追求與感官刺激，故一生「忙過」且「虛度」。\\\\n【詞義與名物】佛教認為，肉身（色身）是短暫無常的，若看不破就會為其欲望所累；真正的生命本體（法身、自性）才是真實的，若不體認便會失去生命的重心。\\\\n【思想與篇章】此章意在勸人回歸內心，尋求真實的精神安頓。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-28","chapterId":"cai-gen-tan_ch-2","order":28,"canonicalText":"芝草無根醴無源，志士當勇奮翼；彩雲易散琉璃脆，達人當早回頭。","sentenceIds":["cai-gen-tan_ch-2_p-28_s-1","cai-gen-tan_ch-2_p-28_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"靈芝的生長本無固定的根基，甘泉的湧出也沒有一成不變的源頭（比喻人的富貴與成就並非天生註定），有志之士應當勇敢地振翅高飛、奮發圖強；美麗的彩雲極易消散，精美的琉璃極易破碎（比喻世俗的榮華富貴極其脆弱無常），通達事理的人應當及早回頭、超脫物外。","analysis":"【主題與背景】本條前半句用「芝草無根，醴泉無源」（出自古語）勉勵士子，說明英雄不問出處，命運掌握在自己手中，應當「勇奮翼」積極進取，體現了儒家的自強不息；後半句用「彩雲易散琉璃脆」（語出白居易《簡簡吟》）警示世人，世間美好與名利極易幻滅，應當「早回頭」淡泊超脫，體現了道禪的無常與出世智慧。\\\\n【詞義與名物】這兩句一進一退，反映了《菜根譚》進退有度、儒道互補的處世哲學。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-29","chapterId":"cai-gen-tan_ch-2","order":29,"canonicalText":"少壯者，事事當用意而意反輕，徒汛汛作水中鳧而已，何以振雲霄之翮？衰老者，事事宜忘情而情反重，徒碌碌為轅下駒而已，何以脫韁鎖之身？","sentenceIds":["cai-gen-tan_ch-2_p-29_s-1","cai-gen-tan_ch-2_p-29_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"年輕力壯的人，做任何事情都應當專心用意、奮發有為，然而他們的心思反而輕飄不專，只是徒然像水中的野鴨一樣隨波漂蕩，這又如何能振翅飛向九霄雲外呢？年老體衰的人，對世俗的事物本應淡泊忘情、頤養天年，然而他們的執著之情反而更加沉重，只是徒然像拉車的馬駒一樣終日碌碌無為，這又如何能擺脫名利韁繩與鎖鏈的束縛呢？","analysis":"【主題與背景】本條針對人生不同階段（少壯與衰老）提出了針對性的反省。少壯時期是建功立業、砥礪志向的黃金時代，若缺乏遠大志向，如「水中鳧」（野鴨）般隨波逐流，便無法成就大業（振雲霄之翮）；衰老時期是功成身退、回歸本真的階段，若依然對名利、子孫過度執著（情反重），如「轅下駒」般不得解脫，便無法獲得心靈的自由（脫韁鎖之身）。\\\\n【詞義與名物】作者指出了世人常犯的生命錯位，勸誡人們在適當的年齡做符合天道規律的事。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-30","chapterId":"cai-gen-tan_ch-2","order":30,"canonicalText":"帆只揚五分，船便安。水只注五分，器便穩。如韓信以勇備震主被擒，陸機以才名冠世見殺，霍光敗於權勢逼君，石崇死於財賦敵國，皆以十分取敗者也。康節雲：「飲酒莫教成酩酊，看花慎勿至離披。」旨哉言乎！","sentenceIds":["cai-gen-tan_ch-2_p-30_s-1","cai-gen-tan_ch-2_p-30_s-2","cai-gen-tan_ch-2_p-30_s-3","cai-gen-tan_ch-2_p-30_s-4","cai-gen-tan_ch-2_p-30_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"帆只揚起五分，船隻行駛就安全；水只注入五分，容器擺放就平穩。例如漢代韓信因為智勇雙全、功高震主而慘遭擒殺，西晉陸機因為才華冠絕當世而引來殺身之禍，西漢霍光因為權勢滔天、威逼君王而導致家族敗亡，西晉石崇因為財富富可敵國而招致殺身之禍，這些人都是因為凡事求全、追求十分滿盈而招致失敗的。邵雍（康節）曾說：「喝酒千萬不要喝到酩酊大醉，觀花時千萬不要等到花朵開到凋謝零落。」這話說得是多麼雋永深刻啊！","analysis":"【主題與背景】本條論述了「持盈保泰」、「凡事留有餘地」的處世智慧，核心在於反對「十分滿盈」。作者列舉歷史上因功高、才顯、權重、富足而招致殺身之禍的歷史名人（韓信、陸機、霍光、石崇），證明「物極必反」、「滿招損」的天道規律。\\\\n【詞義與名物】隨後引用邵雍的詩句「飲酒莫教成酩酊，看花慎勿至離披」（出自《無名歌》），指出中庸、節制的藝術。\\\\n【思想與篇章】這種「凡事留五分」的哲學，是道家保身避禍與儒家中庸思想的完美結合。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-31","chapterId":"cai-gen-tan_ch-2","order":31,"canonicalText":"附勢者如寄生依木，木伐而寄生亦枯；竊利者如𧕍虰盜人，人死而𧕍虰亦滅。始以勢利害人，終以勢利自斃。勢利之為害也，如是夫！","sentenceIds":["cai-gen-tan_ch-2_p-31_s-1","cai-gen-tan_ch-2_p-31_s-2","cai-gen-tan_ch-2_p-31_s-3","cai-gen-tan_ch-2_p-31_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趨炎附勢的人就像依附在大樹上的寄生植物，大樹一旦被砍伐，寄生植物也就隨之枯萎；竊取利益的人就像吸食人血的蝨子跳蚤（𧕍虰），人一旦死亡，蝨子跳蚤也就隨之滅亡。他們開始時利用勢力和利益去危害他人，最終卻因為依仗勢力和利益而使自己喪命。勢利所帶來的危害，竟然是這樣的啊！","analysis":"【主題與背景】本條以極具諷刺意味的比喻，揭示了依附權勢與貪圖私利的寄生本質及其必然覆滅的下場。作者將「附勢者」比作「寄生依木」，將「竊利者」比作吸血的「𧕍虰」（即蝨子、寄生蟲之類）。\\\\n【詞義與名物】這些人缺乏獨立的人格與正當的立身之本，其生存完全依賴於所依附的客體。\\\\n【思想與篇章】一旦客體倒塌（木伐、人死），其自身也必然走向滅亡。這不僅是對功利小人的警告，更是勸誡世人立身行事必須正大光明，保持主體人格的獨立與清白。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-32","chapterId":"cai-gen-tan_ch-2","order":32,"canonicalText":"醉後添杯不如渺渺看雲，興尖納履不如悠悠觀水。","sentenceIds":["cai-gen-tan_ch-2_p-32_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"喝醉之後還要繼續添杯喝酒，不如去觀賞那渺遠無際的白雲；在遊興已盡時還要穿鞋離去，不如留下來悠閒地觀賞那長流的綠水。","analysis":"【訓詁與名物】\\\\n添杯：繼續斟酒。渺渺：遙遠無盡的樣子。興尖：此處「尖」字疑為「盡」或「闌」之誤植，或指興致達到頂點而將衰減之際。納履：穿上鞋子，引申為動身離開。悠悠：悠閒自在，或指水流長遠的樣子。\\\\n【章法與結構】\\\\n本段以對偶句寫成，「醉後」對「興尖」，「添杯」對「納履」，「渺渺看雲」對「悠悠觀水」。句式透過「不如」二字形成一種選擇與轉折，將人為的勉強造作與自然的清雅閒適進行對比，營造出空靈脫俗的意境。\\\\n【思想與義理】\\\\n本段文字旨在表達「適可而止」與「隨遇而安」的生活哲理。飲酒至醉，若再貪杯便流於放縱，失去了品酒的初衷；遊玩至興盡，若急於趕路或勉強延續，反而破壞了心情。與其執著於外在的感官刺激或行程安排，不如停下腳步，把心神寄託於渺渺白雲與悠悠流水之中。這是一種放下執念、回歸自然、與天地萬物合而為一的道家精神與禪宗意趣。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-33","chapterId":"cai-gen-tan_ch-2","order":33,"canonicalText":"鶴立雞羣，可謂超然無侶矣。然進而觀於大海之鵬，則眇然自小。又進而求之九霄之鳳，則巍乎莫及。所以至人常若無若虛，而盛德多不矜不伐也。","sentenceIds":["cai-gen-tan_ch-2_p-33_s-1","cai-gen-tan_ch-2_p-33_s-2","cai-gen-tan_ch-2_p-33_s-3","cai-gen-tan_ch-2_p-33_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仙鶴站在雞羣之中，可以說是非常超羣、沒有同類可以相比了。然而如果進一步去觀看大海上的大鵬鳥，就會顯得渺小微不足道。再進一步去尋求翱翔於九霄之上的鳳凰，那更是高不可攀、遠遠趕不上了。所以，境界極高的人（至人）其心境常常像空無一物、虛懷若谷一樣，而德行崇高的人大多從不自誇，也不自我炫耀。","analysis":"【主題與背景】本條探討了虛懷若谷的修養，說明人外有人、天外有天的道理。以「鶴立雞羣」比喻人在局部環境中的出類拔萃，但這只是相對的。\\\\n【詞義與名物】若放眼於「大海之鵬」與「九霄之鳳」，原有的優越感便會蕩然無存。\\\\n【思想與篇章】因此，真正的「至人」與「盛德」者深諳宇宙之無限與個體之渺小，絕不會因一時一地的成就而沾沾自喜，而是始終保持《易經》中「謙」的品德以及老子「若無若虛」、「不矜不伐」的超然境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-34","chapterId":"cai-gen-tan_ch-2","order":34,"canonicalText":"極思辱者，每自冤恨；極喜歡者，每自遺悔。","sentenceIds":["cai-gen-tan_ch-2_p-34_s-1","cai-gen-tan_ch-2_p-34_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"過度思考自己所受屈辱的人，往往會暗自生出無窮的怨恨；極度沉溺於歡樂喜悅的人，往往會在事後給自己留下無盡的懊悔。","analysis":"【訓詁與名物】「極思辱者」的「極」是過度、極端之意；「辱」指屈辱、受委屈的經歷。「每自」意為往往會自動地、自然而然地。「冤恨」即怨恨、不平之氣。「遺悔」指留下悔恨。\\\\n【章法與結構】此句採用工整的對偶句式，「極思辱者」對「極喜歡者」，「每自冤恨」對「每自遺悔」。前半句談論負面情緒的極端，後半句論述正面情緒過度的結果，正反兩面相互映襯，結構嚴密而對稱，凸顯了物極必反的道理。\\\\n【思想與義理】本段文字深蘊儒道兩家中庸與知止的哲理。作者指出情緒走向極端的危害：過度執著於過去的屈辱，會使心靈深陷於怨恨的泥淖中無法自拔；而過度追逐感官與情緒上的狂歡，又必然會在曲終人散後感到空虛與懊悔。這啟示我們在為人處世時，必須保持內心的平和，不以物喜，不以己悲，避免情緒的極端化，方能求得生命的安寧與圓滿。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-35","chapterId":"cai-gen-tan_ch-2","order":35,"canonicalText":"蛾撲火，火焦蛾，莫謂禍生無本；果種花，花結果，須知福至有因。","sentenceIds":["cai-gen-tan_ch-2_p-35_s-1","cai-gen-tan_ch-2_p-35_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"飛蛾撲向火燄，火燄燒焦了飛蛾，不要說災禍的產生沒有根源（那是因為飛蛾自身的貪光愚昧所致）；果實由花朵發育而來，花朵凋謝後結出果實，應當知道福澤的到來都是有其因緣積累的。","analysis":"【主題與背景】本條闡述了因果報應與自作自受的道理。以「飛蛾撲火，火焦蛾」為喻，說明許多災禍表面上是外在環境造成的，實則是主體自身的盲目、貪婪或愚昧（禍生有本，即自招其禍）所導致；以「果種花，花結果」為喻，說明福報並非憑空降臨，而是如花開結果般，是前期善行與努力積累的自然產物（福至有因）。\\\\n【詞義與名物】此章融合了佛家的因果業報思想與儒家「積善之家必有餘慶，積不善之家必有餘殃」的實踐觀，勸人慎始敬終。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-36","chapterId":"cai-gen-tan_ch-2","order":36,"canonicalText":"車爭險道，馬騁先鞭，到敗處未免噬臍；粟喜堆山，金誇過鬥，臨行時還是空手。","sentenceIds":["cai-gen-tan_ch-2_p-36_s-1","cai-gen-tan_ch-2_p-36_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"乘車在險峻的道路上爭先恐後，騎馬時不斷揮舞馬鞭爭奪第一，等到車翻馬仰、慘遭失敗的時候，恐怕就後悔莫及了；穀物堆積如山而感到欣喜，黃金多得超過斗量而向人炫耀，等到生命終結、撒手人寰的時候，終究還是兩手空空。","analysis":"【主題與背景】本條旨在勸戒世人戒除惡性競爭與貪婪財貨，看透名利的虛妄。前半句以「爭險道」、「騁先鞭」比喻世人在名利場中的激烈角逐，若不知退讓，一旦失敗，將落得「噬臍」（典出《左傳》，比喻後悔莫及）的下場。\\\\n【詞義與名物】後半句以「粟堆山」、「金過鬥」比喻財富的聚斂，以「臨行空手」揭示死亡面前人人平等的真相。\\\\n【思想與篇章】這融合了道家的「不爭」與佛家「萬般帶不去，唯有業隨身」的無常觀，勸導世人追求心靈的寧靜而非物質的虛名。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-37","chapterId":"cai-gen-tan_ch-2","order":37,"canonicalText":"花逞春光，一番雨、一番風，催歸塵土；竹堅雅操，幾朝霜、幾朝雪，傲就瑯玕。","sentenceIds":["cai-gen-tan_ch-2_p-37_s-1","cai-gen-tan_ch-2_p-37_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鮮花在春光中炫耀美麗，然而只要經歷幾番風雨的摧殘，就會被催促著飄零凋落、化為塵土；竹子堅守高雅的操守，哪怕經歷幾度嚴霜、幾番白雪的洗禮，反而磨礪成就瞭如青玉（瑯玕）般翠綠挺拔的身姿。","analysis":"【主題與背景】本條通過「花」與「竹」的對比，形象地說明瞭虛榮短暫與堅貞持久的人生道理。花朵雖然在春天豔麗一時（逞春光），但缺乏耐受力，稍遇風雨便歸於塵土，比喻那些得志一時、虛浮無根的權貴與名利客。\\\\n【詞義與名物】竹子雖然平淡，但有堅貞之節，在嚴寒的霜雪中（幾朝霜雪）愈發顯得青翠，終成「瑯玕」（青色的美玉，此指翠竹）。\\\\n【思想與篇章】這勉勵君子應如竹般經得起命運磨難，在逆境中人格得到磨礪，成就真正的道德學問。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-38","chapterId":"cai-gen-tan_ch-2","order":38,"canonicalText":"富貴是無情之物，看得他重，他害你越大；貧賤是耐久之交，處得他好，他益你深。故貪商於而戀金谷者，竟被一時之顯戮；樂簞瓢而甘敝縕者，終享千載之令名。","sentenceIds":["cai-gen-tan_ch-2_p-38_s-1","cai-gen-tan_ch-2_p-38_s-2","cai-gen-tan_ch-2_p-38_s-3","cai-gen-tan_ch-2_p-38_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"富貴是個冷酷無情的東西，你越是把它看得重，它對你的傷害就越深；貧賤是個經得起時間考驗的知己，你若能安然與它相處，它對你的裨益就越深厚。所以，那些貪圖商於之地而遭欺騙、留戀金谷園奢華生活的人，最終竟然在一時之間慘遭殺戮；而那些樂於簞食瓢飲、甘心身穿破舊麻衣的人，卻能終身享受流傳千載的美名。","analysis":"【主題與背景】本條對富貴與貧賤的價值進行了深刻的逆向思考。富貴雖好，但伴隨著貪婪、嫉妒與殺機，越是執著越易招禍。\\\\n【詞義與名物】貧賤雖苦，卻能磨練人的意志，讓人回歸簡單的生活與純真的心性。\\\\n【思想與篇章】作者引用了歷史典故：「貪商於」指戰國時楚懷王貪圖秦國張儀許諾的「商於之地六百里」，輕信秦國，最終導致楚國兵敗、自己被囚死於秦的悲劇；「戀金谷」指西晉鉅富石崇，他在金谷園過著極度奢華的生活，因不肯割愛妾綠珠，最終被趙王倫的黨羽孫秀所殺。而「樂簞瓢」則指顏回（一簞食，一瓢飲）；「甘敝縕」指子路（衣敝縕袍，與衣狐貉者立而不知恥）。全篇旨在勸勉世人戒奢崇儉，在淡泊中保全聲名與生命。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-39","chapterId":"cai-gen-tan_ch-2","order":39,"canonicalText":"鴿惡鈴而高飛，不知斂翼而鈴自息；人惡影而疾走，不知處陰而影自滅。故愚夫徒疾走高飛，而平地反為苦海；達士知處陰斂翼，而巉巖亦是坦途。","sentenceIds":["cai-gen-tan_ch-2_p-39_s-1","cai-gen-tan_ch-2_p-39_s-2","cai-gen-tan_ch-2_p-39_s-3","cai-gen-tan_ch-2_p-39_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鴿子厭惡身上的鈴聲而拚命高飛，卻不知道只要收攏翅膀停止飛行，鈴聲自然就會平息；人害怕自己的影子而拚命奔跑，卻不知道只要走到陰涼遮蔽的地方，影子自然就會消失。所以，愚笨的人只懂得盲目地奔跑與高飛，結果反而把平坦的土地變成了痛苦的深淵；通達的智者懂得走入陰涼處、收斂羽翼，即使是險峻的山崖在他們眼中也是平坦的道路。","analysis":"【主題與背景】本條採用了兩個寓言，深入剖析了世人因解決問題的方法不當而自尋煩惱的心理。「鴿惡鈴而高飛」：鴿子越飛鈴聲越響，其實只要停下來（斂翼），鈴聲即止；「人惡影而疾走」：典出《莊子·漁父》「人有畏影惡跡而走之者……處陰以休影，處靜以息跡」。\\\\n【詞義與名物】人越跑，影越隨，且累死於途；其實只要走到陰涼處，影子自滅。\\\\n【思想與篇章】這兩個比喻極具哲理，說明世人為了解脫痛苦、求得名利，往往採取向外奔競、愈陷愈深的方式（疾走高飛），結果把人生（平地）變成了苦海。而智者懂得「內省」、「退步」與「放下」（處陰斂翼），從根本上消除欲望與妄想，自然能隨遇而安，將險境化為坦途。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-40","chapterId":"cai-gen-tan_ch-2","order":40,"canonicalText":"秋蟲春鳥共暢天機，何必浪生悲喜；老樹新花同含生意，胡為妄別媸妍。","sentenceIds":["cai-gen-tan_ch-2_p-40_s-1","cai-gen-tan_ch-2_p-40_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"秋天的鳴蟲與春天的飛鳥同樣都在展現著大自然的生機，何必徒然產生悲傷與喜悅的分別；蒼老的大樹與嬌嫩的新花同樣都蘊含著勃勃生機，又何必妄自區分它們的醜陋與美麗呢？","analysis":"【主題與背景】本條體現了莊子的「齊物」思想與禪宗的「無分別智」。在大自然（天機、生意）的視角下，秋蟲的悲鳴與春鳥的歡歌、老樹的乾枯與新花的絢爛，都是生命律動的同等展現，沒有本質的優劣與美醜。\\\\n【詞義與名物】世人之所以有悲喜（傷秋喜春）和媸妍（厭老愛新）的分別，是因為站在了自我主觀的偏見與利害關係上。\\\\n【思想與篇章】作者呼籲回歸大自然的本初狀態，消除分別心，從而獲得與萬物同遊的曠達心境。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-41","chapterId":"cai-gen-tan_ch-2","order":41,"canonicalText":"多栽桃李少栽荊，便是開條福路；不積詩書偏積玉，還如築個禍基。","sentenceIds":["cai-gen-tan_ch-2_p-41_s-1","cai-gen-tan_ch-2_p-41_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"多栽植桃花李樹（比喻廣結善緣、培育人才），少種植荊棘（比喻不與人結怨、不製造障礙），這就是在為自己開闢一條幸福的道路；不積累文化知識與聖賢詩書，反而一味聚斂金銀珠玉，這就像是在為自己築造一個招致災禍的根基。","analysis":"【主題與背景】本條是一篇直白的道德與家門修養規箴。「桃李」在傳統文化中比喻優秀的人才（桃李滿天下）或善行，多栽桃李即是廣行善事、惠澤他人；「荊」即荊棘，多種荊棘比喻作惡、設障。\\\\n【詞義與名物】後半句則批評了「重利輕儒」的家風，指出金銀珠玉（積玉）若無道德知識（詩書）來支配，往往會淪為子孫驕奢淫逸或招致外人覬覦的導火線（禍基）。\\\\n【思想與篇章】這契合了儒家「道德傳家遠，詩書繼世長」的家庭教育理念。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-42","chapterId":"cai-gen-tan_ch-2","order":42,"canonicalText":"萬境一轍原無地，著個窮通；萬物一體原無處，分個彼我。世人迷真逐妄，乃向坦途上自設一坷坎，從空洞中自築一藩籬。良足慨哉！","sentenceIds":["cai-gen-tan_ch-2_p-42_s-1","cai-gen-tan_ch-2_p-42_s-2","cai-gen-tan_ch-2_p-42_s-3","cai-gen-tan_ch-2_p-42_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世間的萬般境遇本來都是同一個道理，哪裡有地方可以容納並區分什麼「困頓」與「發達」；宇宙間的萬事萬物本來都是融合一體的，又在哪裡可以劃分出什麼「他人」與「自我」。世俗之人執迷於真實而追逐著虛妄，竟然在平坦的大道上給自己設置一道道坎坷，在空曠無礙的虛空中給自己築起一座座籬笆。這真值得讓人深沉慨嘆啊！","analysis":"【主題與背景】本條深刻地批判了世俗對立觀念對心靈的禁錮，融匯了儒家的「萬物一體之仁」（孟子、程顥）、道家的「天地與我並生，萬物與我為一」（莊子）以及佛教的「無二法門」。在萬物融合的本源狀態下，並沒有客觀的「窮與通」（命運順逆）和「彼與此」（人我對立）。\\\\n【詞義與名物】世人之所以痛苦，是因為產生了二元對立的分別執著（迷真逐妄），這就如同在坦途上設坎、在虛空中築牆（自築藩籬），作繭自縛。\\\\n【思想與篇章】只有打破這些心靈的藩籬，才能重獲本自具足的自在與解脫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-43","chapterId":"cai-gen-tan_ch-2","order":43,"canonicalText":"大聰明的人，小事必朦朧；大懵懂的人，小事必伺察。蓋伺察乃懵懂之根，而朦朧正聰明之窟也。","sentenceIds":["cai-gen-tan_ch-2_p-43_s-1","cai-gen-tan_ch-2_p-43_s-2","cai-gen-tan_ch-2_p-43_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"具有大智慧、大聰明的人，在處理無關緊要的小事時必定顯得模稜兩可、糊裡糊塗；而真正糊塗、愚昧的人，在面對小事時卻往往要嚴密地窺伺察看。因為處處嚴密伺察正是愚昧糊塗的根源，而小事上的朦朧糊塗恰恰是大聰明的藏身之處。","analysis":"【主題與背景】本條闡述了「大智若愚」與「難得糊塗」的精微哲理。大聰明者（大聰明）有大格局，明白精力應放在根本大事上，在無傷大雅的小事上故意裝糊塗（朦朧），這樣既能寬容他人，又能保護自己的心神，故「朦朧正聰明之窟」；而真正愚蠢者（大懵懂）缺乏大局觀，卻極度敏感於細枝末節，處處猜忌、斤斤計較（伺察），這不僅讓自己心力交瘁，也容易招致怨恨，故「伺察乃懵懂之根」。\\\\n【詞義與名物】這與《老子》「其政悶悶，其民淳淳；其政察察，其民缺缺」的治世智慧相通。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-44","chapterId":"cai-gen-tan_ch-2","order":44,"canonicalText":"大烈鴻猷，常出悠閑鎮定之士，不必忙忙；休徵景福，多集寬洪長厚之家，何須瑣瑣。","sentenceIds":["cai-gen-tan_ch-2_p-44_s-1","cai-gen-tan_ch-2_p-44_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"偉大的功業與宏大的規劃，常常是由那些神態悠閒、臨事鎮定的人所創立，用不著終日忙忙碌碌、行色匆匆；吉祥的徵兆與宏大的福澤，大多匯集在胸懷寬廣、為人敦厚的人家，又何必斤斤計較於瑣碎的小事。","analysis":"【主題與背景】本條論述了「鎮定」與「寬厚」對於成就大業與積累福德的重要性。前半句「大烈鴻猷」（出自《尚書》，指偉大功業與宏大謀略）強調非凡的事業需要臨大節而不奪的靜氣與戰略定力（悠閑鎮定），如謝安淝水之戰圍棋弈墅，反對盲目奔忙（不必忙忙）。\\\\n【詞義與名物】後半句「休徵景福」（吉兆與大福）指出福報的積累依賴於主體的氣量（寬洪長厚），因為寬厚能容納萬物，而「瑣瑣」（斤斤計較、狹隘小氣）則會把福氣推開。\\\\n【思想與篇章】這融合了儒家君子溫泰的氣象與道家靜水流深的道理。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-45","chapterId":"cai-gen-tan_ch-2","order":45,"canonicalText":"貧士肯濟人，纔是性天中惠澤；鬧場能學道，方為心地上工夫。","sentenceIds":["cai-gen-tan_ch-2_p-45_s-1","cai-gen-tan_ch-2_p-45_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"貧窮的讀書人如果願意慷慨解囊去救濟他人，這才是出自本真天性的純潔恩惠；在喧囂紛擾的喧鬧場所中依然能夠潛心修行、學習道法，這才是真正考驗心性磨礪的真功夫。","analysis":"【主題與背景】本條指出了道德實踐與心性修養的兩個極高境界：一是「貧士濟人」，富貴者濟人或許是餘力所及，甚至為了名利；而貧窮者生活本已艱難，此時若能「肯濟人」，完全是出於內心最純粹的悲憫與善良（性天中惠澤），毫無功利之心。二是「鬧場學道」，在寂靜山林中修行相對容易，而在「鬧場」（如市井、名利場、喧囂處）中，面對無數誘惑與幹擾，若能保持定力學道，才是真正的「心地上工夫」（即王陽明所謂「人須在事上磨，方立得住」）。\\\\n【詞義與名物】這體現了《菜根譚》不脫離世俗而超然世俗的實踐美學。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-46","chapterId":"cai-gen-tan_ch-2","order":46,"canonicalText":"人生只為欲字所累，便如馬如牛，聽人羈絡；為鷹為犬，任物鞭笞。若果一念清明，淡然無欲，天地也不能轉動我，鬼神也不能役使我，況一切區區事物乎！","sentenceIds":["cai-gen-tan_ch-2_p-46_s-1","cai-gen-tan_ch-2_p-46_s-2","cai-gen-tan_ch-2_p-46_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人生只要被一個「欲」字所牽累，就會像牛馬一樣，聽憑他人套上韁繩與籠頭；像獵鷹和獵犬一樣，任由外物鞭打和驅使。如果能真正做到心頭存有一念清明，淡泊名利而毫無私欲，那麼連天地都無法動搖我的心志，鬼神也無法役使我的靈魂，更何況是世間這一切微不足道的區區事物呢？","analysis":"【主題與背景】本條強烈地宣示了「無欲則剛」的精神獨立性。作者將被慾望奴役的人比作「牛馬」、「鷹犬」，失去主體人格的自由，受制於外物與他人。\\\\n【詞義與名物】而一旦通過心性修養達到「一念清明，淡然無欲」的境界，心靈便獲得了絕對的自由與強大的力量。\\\\n【思想與篇章】此時主體與天地同大，任何外在的權勢、名利甚至超自然力量（天地、鬼神）都無法撼動、役使他。此思想繼承了孟子「說大人，則藐之」的大丈夫氣概，以及《道德經》「無欲以觀其妙」的精神。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-47","chapterId":"cai-gen-tan_ch-2","order":47,"canonicalText":"貪得者身富而心貧，知足者身貧而心富；居高者形逸而神勞，處下者形勞而神逸。孰得孰失，孰幻孰真，達人當自辨之。","sentenceIds":["cai-gen-tan_ch-2_p-47_s-1","cai-gen-tan_ch-2_p-47_s-2","cai-gen-tan_ch-2_p-47_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"貪得無厭的人縱然身體與物質富有，內心卻極度貧窮；知足常樂的人縱然身體與物質貧窮，心靈卻無比富足。身居高位的人雖然身體安逸，精神卻極度勞累；處於低下地位的人雖然身體勞碌，精神卻十分安逸。這中間究竟誰得到、誰失去，哪一個是虛幻、哪一個是真實，通達事理的智者應當自己明辨。","analysis":"【主題與背景】本條通過兩組鮮明的對比（富與貧、高與下、身與心、形與神），探討了幸福與價值的真諦。物質的富有（身富）不等於精神的幸福，反而因永無止境的貪欲而陷入「心貧」；物質的匱乏（身貧）若能以「知足」對待，便能享受「心富」的安寧。\\\\n【詞義與名物】同樣，權力巔峯（居高）伴隨著無盡的算計與焦慮（神勞）；平凡地位（處下）雖有體力勞作（形勞），但沒有政治鬥爭與利益牽絆（神逸）。\\\\n【思想與篇章】這引導人們從虛幻的外在名利轉向追求真實的內心和諧，是老子「知足不辱，知止不殆」思想的具體延伸。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-48","chapterId":"cai-gen-tan_ch-2","order":48,"canonicalText":"眾人以順境為樂，而君子樂自逆境中來；眾人以拂意為憂，而君子憂從快意處起。蓋眾人憂樂以情，而君子憂樂以理也。","sentenceIds":["cai-gen-tan_ch-2_p-48_s-1","cai-gen-tan_ch-2_p-48_s-2","cai-gen-tan_ch-2_p-48_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一般人把身處順境看作快樂，而君子卻能在逆境的磨鍊中體會到快樂；一般人因為事情不順心而憂愁，而君子卻在事情過分順遂如意的時候生起憂患意識。這是因為一般人的憂愁與快樂是隨著主觀情感起伏的，而君子的憂愁與快樂則是依據天理與規律來判斷的。","analysis":"【主題與背景】本條論述了「君子」與「眾人」在憂樂觀上的本質差別，屬於宋代理學「憂樂以理」的範疇。普通人隨外境而動（憂樂以情），順則喜，逆則憂。\\\\n【詞義與名物】君子則深諳「生於憂患，死於安樂」的道理（憂樂以理）：逆境是砥礪德行、增長才幹的熔爐，故能「樂自逆境中來」；順境與「快意」之時往往最易讓人放鬆警惕、滋生驕奢，故需「憂從快意處起」（防微杜漸）。\\\\n【思想與篇章】這種超越感性直覺、訴諸客觀理性的憂樂觀，是君子人格成熟的標誌。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-49","chapterId":"cai-gen-tan_ch-2","order":49,"canonicalText":"謝豹覆面，猶知自愧；唐鼠易腸，猶知自悔。蓋愧悔二字，乃吾人去惡遷善之門，起死回生之路也。人生若無此念頭，便是既死之寒灰，已枯之槁木矣。何處討些生理？","sentenceIds":["cai-gen-tan_ch-2_p-49_s-1","cai-gen-tan_ch-2_p-49_s-2","cai-gen-tan_ch-2_p-49_s-3","cai-gen-tan_ch-2_p-49_s-4","cai-gen-tan_ch-2_p-49_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"據說謝豹（一種鳥）用翅膀遮住臉面，還懂得自我羞愧；唐鼠（一種野鼠）甚至想交換腸肚，還懂得自我懺悔。可見「慚愧」與「悔改」這兩個詞，正是我們去除惡行、遷善向上的門徑，是靈魂起死回生的道路啊。人活著如果沒有這點慚愧與悔改的念頭，那就成了已經熄滅의冷灰、已經枯死之槁木矣，又從哪裡能尋得一絲活潑潑的生命生機呢？","analysis":"【主題與背景】本條借用兩個古代生物傳說，強調「慚愧」與「懺悔」對於人性覺醒與修養的至關重要性。「謝豹覆面」：謝豹即杜鵑鳥的一種，傳說其常啼血，因自感聲音哀怨或形體不美而以翼覆面，古人將其視為懂得羞愧的象徵；「唐鼠易腸」：唐鼠又稱鼱鼩或唐鼠，古代傳說其食不潔之物後會吐出胃腸進行清洗（或悔恨其食），比喻洗心革面、自我痛悔。\\\\n【詞義與名物】作者指出，愧悔之心是人去惡向善（去惡遷善）的起點。\\\\n【思想與篇章】如果人喪失了廉恥心與反省能力，心靈就會徹底乾枯死寂（寒灰槁木），失去生機與生命力（生理）。這與孟子「無羞惡之心，非人也」的思想相呼應。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-50","chapterId":"cai-gen-tan_ch-2","order":50,"canonicalText":"異寶奇琛，俱是必爭之器；瑰節奇行，多冒不祥之名。總不若尋常歷履易簡行藏，可以完天地渾噩之真，享民物和平之福。","sentenceIds":["cai-gen-tan_ch-2_p-50_s-1","cai-gen-tan_ch-2_p-50_s-2","cai-gen-tan_ch-2_p-50_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"奇珍異寶，都是人們必定會去爭奪的危險器物；過於清高孤傲的志節與標新立異的奇特行為，大多會冒著招致不祥之兆的聲名。這些都遠遠比不上過著平尋常凡的經歷、實行平易簡單的處世進退，這樣才可以保全天地間自然渾厚樸實的本真，享受人世與萬物平靜和諧的福澤。","analysis":"【主題與背景】本條論述了「平淡歸真」、「大巧若拙」的處世哲學，蘊含深厚的道家智慧。奇珍異寶因其稀有而引發爭奪（必爭之器，典出《老子》「不貴難得之貨，使民不為盜」）；同樣，行為與志節過於標新立異、孤高脫俗（瑰節奇行），容易引起世俗的嫉妒與非議，甚至帶來災禍（不祥之名）。\\\\n【詞義與名物】因此，最安全且符合天道的處世方式是「易簡行藏」（平易簡單的行止），這與《易經·繫辭》「易簡而天下之理得矣」相通。\\\\n【思想與篇章】在平凡中保全本真（渾噩之真），才能享受真正的和平之福。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-51","chapterId":"cai-gen-tan_ch-2","order":51,"canonicalText":"福善不在杳冥，即在食息起居處牖其衷；禍淫不在幽渺，即在動靜語默間奪其魄。可見人之精爽常通於天，於之威命即寓於人，天人豈相遠哉！","sentenceIds":["cai-gen-tan_ch-2_p-51_s-1","cai-gen-tan_ch-2_p-51_s-2","cai-gen-tan_ch-2_p-51_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"上天造福行善之人，並非發生在玄妙幽遠的虛無之中，而是在其日常生活、飲食起居的最平常處，默默地啟迪與開導他的心靈；上天懲罰淫邪作惡之人，也並非發生在隱祕虛無的縹緲之處，而是在其一動一靜、一語一默的日常行止間，不知不覺地奪去他的魂魄與神智。由此可見，人的精神與靈魂是時刻與上天相通的，上天的威嚴與懲處正是寄寓在人的日常生活與精神狀態之中，天與人難道相隔很遙遠嗎？","analysis":"【主題與背景】本條深刻探討了「天人合一」與「因果即在當下」的哲理。在中國哲學中，「天人感應」與「天道承負」並非神祕的外在神祇裁決，而是融於人的日常生活與心性之中。\\\\n【詞義與名物】上天的「福善」表現為善人內心的安詳、智慧與光明（食息起居處牖其衷）；上天的「禍淫」則表現為惡人內心的恐懼、狂亂與心神不寧（動靜語默間奪其魄）。\\\\n【思想與篇章】作者指出「天人豈相遠哉」，天理即人心，人的精神與宇宙法則時刻相通。這既是儒家「敬畏天命」的體現，也是佛教「心即是法」的寫照。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-52","chapterId":"cai-gen-tan_ch-2","order":52,"canonicalText":"晝閑人寂，聽數聲鳥語悠揚，不覺耳根盡徹；夜靜天高，看一片雲光舒捲，頓令眼界俱空。","sentenceIds":["cai-gen-tan_ch-2_p-52_s-1","cai-gen-tan_ch-2_p-52_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"白天清閒，四周寂靜，聽著幾聲悠揚的鳥鳴，不知不覺中耳根感到無比清澈澄明；夜深人靜，天空高遠，看著一片雲彩隨風舒展收卷，頓時讓人的眼界與心胸都變得空靈開闊。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈應酬〉第 125 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「晝閑人寂聽數聲鳥語悠揚不覺耳根盡徹夜靜天……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「晝」、「閑」、「人」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-2_p-52）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-53","chapterId":"cai-gen-tan_ch-2","order":53,"canonicalText":"世事如棋局，不著得纔是高手；人生似瓦盆，打破了方見真空。","sentenceIds":["cai-gen-tan_ch-2_p-53_s-1","cai-gen-tan_ch-2_p-53_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世間的俗事就像一盤棋局，只有不落子、不涉入爭奪的人才是真正的高手；人生如同一個泥製的瓦盆，唯有將其打破、擺脫物質的束縛，才能看見真正的空性本質。","analysis":"【主題與背景】此段以「棋局」喻世事的紛擾博弈，以「瓦盆」喻人生的肉身與名利束縛。\\\\n【詞義與名物】「不著得」指不執著於局中的勝負得失，體現了道家「無為」與不爭的超然；「打破瓦盆」則借用佛教禪宗「打破漆桶」的公案，隱喻打破自我執著（我執）與法執，唯有粉碎對世俗皮相的依賴，才能證悟萬法皆空的「真空」智慧，獲得精神上的絕對自由。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-54","chapterId":"cai-gen-tan_ch-2","order":54,"canonicalText":"龍可豢非真龍，虎可搏非真虎，故爵祿可餌榮進之輩，必不可籠淡然無欲之人；鼎鑊可及寵利之流，必不可加飄然遠引之士。","sentenceIds":["cai-gen-tan_ch-2_p-54_s-1","cai-gen-tan_ch-2_p-54_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"可以被豢養的龍並非真正的神龍，可以被搏鬥制服的虎並非真正的猛虎。所以，爵位與俸祿只能誘惑那些汲汲於榮華富貴、圖謀進取的人，卻絕對無法籠絡恬淡無欲、看輕名利的人；刑具與嚴刑峻法只能懲治那些執著於受寵圖利的人，卻絕對無法加害於那些超然物外、隱遁遠避的隱逸之士。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈應酬〉第 127 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「龍可豢非真龍虎可搏非真虎故爵祿可餌榮進之……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「龍」、「可」、「豢」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-2_p-54）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-55","chapterId":"cai-gen-tan_ch-2","order":55,"canonicalText":"一場閑富貴，狠狠爭來，雖得還是失；百歲好光陰，忙忙過了，縱壽亦為殀。","sentenceIds":["cai-gen-tan_ch-2_p-55_s-1","cai-gen-tan_ch-2_p-55_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一場如過眼雲煙般的無聊富貴，如果費盡心機、狠狠爭奪而來，即使得到了，本質上依然是一種失去；短暫的百歲美好光陰，如果終日忙忙碌碌、無暇自得地度過，縱使活得長壽，實際上也等同於夭折。","analysis":"【主題與背景】本段旨在批判世人對名利的盲目追求，並重申生命的真實價值。作者將世俗富貴斥為「閑富貴」（虛浮無用的富貴），指出因爭奪富貴而喪失了本真與心靈的平靜，是得不償失的。\\\\n【詞義與名物】「忙忙過了」則指靈魂被外物奴役，失去了對生命意義的體會。\\\\n【思想與篇章】莊子曾言「壽即為殀」，若一生未曾覺醒，雖活百歲亦如夭亡。此言警示人們應珍視當下的光陰，追求心靈的閒適與真我的安寧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-56","chapterId":"cai-gen-tan_ch-2","order":56,"canonicalText":"高車嫌地僻，不如魚鳥解親人。駟馬喜門高，怎似鶯花能避俗。","sentenceIds":["cai-gen-tan_ch-2_p-56_s-1","cai-gen-tan_ch-2_p-56_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"乘著高貴馬車的人會嫌棄地方偏僻冷落，不如水中的遊魚與空中的飛鳥那樣懂得親近人類；駕著四匹駿馬的達官顯貴喜歡門第高大顯赫，哪裡比得上鶯歌燕舞、紅花綠葉那般能夠避開世俗的紛擾。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈應酬〉第 129 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「高車嫌地僻不如魚鳥解親人駟馬喜門高怎似鶯……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「高」、「車」、「嫌」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-2_p-56）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-57","chapterId":"cai-gen-tan_ch-2","order":57,"canonicalText":"紅燭燒殘，萬念自然厭冷；黃梁夢破，一身亦似雲浮。","sentenceIds":["cai-gen-tan_ch-2_p-57_s-1","cai-gen-tan_ch-2_p-57_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當紅燭燃盡、繁華落幕之時，心中原本熱切的萬種慾念自然會變得灰暗冷淡；當黃粱美夢驚醒之後，便會恍然發覺自身的存在也如同天上浮雲般虛幻無常。","analysis":"【訓詁與名物】「紅燭燒殘」借指宴席結束或繁華景象消退之時；紅燭常象徵富貴與歡樂。「萬念」指種種世俗的欲望與執念。「厭冷」意為厭倦與冷淡。「黃梁夢破」典出唐代沈既濟《枕中記》，盧生在邯鄲客店遇道士呂翁，枕其青瓷枕入睡，夢中享盡榮華富貴，醒來時店家煮的黃粱米飯尚未熟，藉此比喻榮華富貴如夢幻泡影。「雲浮」比喻人生的漂泊不定與虛無縹緲。\\\\n【章法與結構】全句以對仗形式呈現，「紅燭燒殘」對「黃梁夢破」，「萬念自然厭冷」對「一身亦似雲浮」。從外在情境的變換（燭殘、夢破）過渡到內在心境與人生觀的徹悟（念冷、身浮），上下兩聯語意相輔相成，極具詩意與哲理美感。\\\\n【思想與義理】此句充滿了濃厚的佛道禪意與人生如夢的感歎。透過紅燭燃盡與黃粱夢醒兩個意象，深刻揭示了世俗繁華與功名利祿的短暫與虛幻。人們在繁華過後或是大夢初醒時，往往能看穿欲望的本質，體悟到生命的無常。這教導我們不應過分執著於外在的物質追求與名利得失，而應看淡世事，保持心靈的超脫與寧靜，隨遇而安。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-58","chapterId":"cai-gen-tan_ch-2","order":58,"canonicalText":"千載奇逢，無如好書良友；一生清福，只在椀茗爐煙。","sentenceIds":["cai-gen-tan_ch-2_p-58_s-1","cai-gen-tan_ch-2_p-58_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"千載難逢的奇妙際遇，莫過於讀到一本好書、結識一位良友；人一生能享受的最大清福，其實只在於一碗清茶與一縷爐煙的清閒之中。","analysis":"【主題與背景】本段體現了晚明文人獨特的生活美學與精神追求。在繁複紛擾的社會中，作者將「好書良友」視為最珍貴的精神寄託，將「椀茗爐煙」視為世間至樂。\\\\n【詞義與名物】這是一種化繁為簡、返璞歸真的生活哲學，強調不以物質的多寡來衡量幸福，而是退回內心的寧靜，在日常的茶香與爐煙中體會生命的質樸與自在，屬於典型的文人清玩之樂。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-59","chapterId":"cai-gen-tan_ch-2","order":59,"canonicalText":"蓬茅下誦詩讀書，日日與聖賢晤語，誰雲貧是病？樽壘邊幕天席地，時時共造化氤氳，孰謂醉非禪？興來醉倒落花前，天地即為衾枕。機息坐忘盤石上，古今盡屬蜉蝣。","sentenceIds":["cai-gen-tan_ch-2_p-59_s-1","cai-gen-tan_ch-2_p-59_s-2","cai-gen-tan_ch-2_p-59_s-3","cai-gen-tan_ch-2_p-59_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在簡陋的茅草屋下誦讀詩書，每天都像在與古代聖賢面對面談話，誰說貧窮是一種疾病？在酒樽與酒杯旁以天為幕、以地為席，時時與大自然的生氣融為一體，誰說醉酒不是一種參禪？興來醉倒落花前，天地即為衾枕。機息坐忘盤石上，古今盡屬蜉蝣。","analysis":"【主題與背景】此段洋溢著莊子「天地與我並生，而萬物與我為一」的宇宙觀與魏晉名士的狂放風骨。「誰雲貧是病」表明了儒家守道安貧的精神；「孰謂醉非禪」則融合了禪宗的隨緣任性與道家的忘我境界。\\\\n【詞義與名物】文中的「坐忘」是《莊子》的核心概念，指墮肢體、黜聰明、離形去知，同於大通。\\\\n【思想與篇章】作者藉此表明，當人消除心機（機息），融入自然，就能超越時間（古今）與空間的束縛，體悟到宇宙的無限與生命的逍遙。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-60","chapterId":"cai-gen-tan_ch-2","order":60,"canonicalText":"昂藏老鶴雖飢，飲啄猶閒，肯同雞鶩之營營而競食？偃蹇寒松縱老，豐標自在，豈似桃李之灼灼而爭妍！","sentenceIds":["cai-gen-tan_ch-2_p-60_s-1","cai-gen-tan_ch-2_p-60_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"氣宇軒昂的老鶴雖然飢餓，但飲水啄食依然顯得安詳自若，豈肯像雞鴨那樣為了一點食物而爭奪奔忙？高聳盤曲的寒冬古松縱然老去，其風骨儀態依然自在超俗，哪裡會像桃花李花那樣開得鮮豔奪目去爭奇鬥艷！","analysis":"【主題與背景】此段以「老鶴」與「寒松」自況，象徵潔身自好、堅貞不屈的君子品格；以「雞鶩」與「桃李」比喻世俗中追逐名利、諂媚討好的庸俗之輩。「營營競食」與「灼灼爭妍」生動描繪了世俗名利場中的紛擾。\\\\n【詞義與名物】此段融合了儒家「君子固窮」的操守與道家「超然獨立」的精神，強調即使處於困境或歲月漸老，也應保持高尚的尊嚴與獨立的人格，不與世俗同流合汙。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-61","chapterId":"cai-gen-tan_ch-2","order":61,"canonicalText":"吾人適志於花柳爛熳之時，得趣於笙歌騰沸之處，乃是造化之幻境，人心之蕩念也。須從木落草枯之後，向聲希味淡之中，覓得一些消息，纔是乾坤的橐籥，人物的根宗。","sentenceIds":["cai-gen-tan_ch-2_p-61_s-1","cai-gen-tan_ch-2_p-61_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"我們在鮮花盛開、柳色燦爛的時候感到愜意，在笙歌鼎沸、熱鬧非凡的地方得到樂趣，這其實只是大自然一時呈現的幻境，以及人心受到外物誘惑而產生的放蕩雜念。必須在落葉草枯的蕭瑟季節，在聲音稀少、味道清淡的寧靜之中，去尋覓體會生命深處的玄機，那才是天地運行的根本樞紐，也是人類與萬物的根本源頭。","analysis":"【主題與背景】本段探討了感官愉悅與生命本質的區別，深具老子「五色令人目盲，五音令人耳聾」的哲理。「花柳爛熳」與「笙歌騰沸」是動態的、短暫的表象（幻境與蕩念）；而「木落草枯」與「聲希味淡」則是靜態的、本質的常態。\\\\n【詞義與名物】老子以「橐籥」（風箱）比喻天地之間虛而不屈、動而愈出的本源力量。\\\\n【思想與篇章】作者指出，只有在喧囂褪去、歸於平淡的境界中，才能洞察天地的本源（乾坤之橐籥）與生命的真諦（人物之根宗）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-62","chapterId":"cai-gen-tan_ch-2","order":62,"canonicalText":"靜處觀人事，即伊呂之勳庸、夷齊之節義，無非大海浮漚；閒中玩物情，雖木石之偏枯、鹿豕之頑蠢，總是吾性真如。","sentenceIds":["cai-gen-tan_ch-2_p-62_s-1","cai-gen-tan_ch-2_p-62_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在冷靜的旁觀者角度觀察世間人事，即使是像伊尹、呂尚那樣的宏圖偉業，或是伯夷、叔齊那樣的貞烈節義，也不過是大海上轉瞬即逝的泡沫；在閒適的心境中體悟萬物之情，即使是枯木頑石的殘缺、鹿豬等野獸的愚蠢，也都無一不彰顯著我們自性中真實不虛的佛性與本真。","analysis":"【主題與背景】此段融合了佛教「真如」思想與莊子的萬物齊一論。「伊呂勳庸、夷齊節義」是世俗價值體系中的最高標準（功名與道德），但在無限的時間與空間（大海）面前，皆如「浮漚」（泡沫）般虛妄短暫，體現了般若空宗的視角。\\\\n【詞義與名物】相反地，在擺脫功利心的「閒中」，即便是被視為無知無用的「木石鹿豕」，也各自保有其自然的本性，與人的「自性真如」無二無別。\\\\n【思想與篇章】這表達了對生命與自然本質的深刻關懷與平等觀待。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-63","chapterId":"cai-gen-tan_ch-2","order":63,"canonicalText":"花開花謝春不管，拂意事休對人言；水煖水寒魚自知，會心處還期獨賞。","sentenceIds":["cai-gen-tan_ch-2_p-63_s-1","cai-gen-tan_ch-2_p-63_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"花朵的盛開與凋謝春天並不在意，因此遇到不如意的事情也不必向人抱怨訴苦；水的溫暖與寒冷唯有魚兒自己最清楚，因此心中有所體悟與契合之處，還是應當獨自品味欣賞。","analysis":"【主題與背景】本段展現了極高的心靈自主性與超然態度。「花開花謝春不管」象徵自然規律的無情與客觀，暗示人間的榮辱得失也是自然常態，不必向外求同情或抱怨（「拂意事休對人言」）。\\\\n【詞義與名物】「水煖水寒魚自知」改編自禪宗名言「如人飲水，冷暖自知」，強調生命的體驗與開悟是高度個人化的，無法以言語完全傳達，因此「會心處」唯有在孤獨中默默玩味，體現了不假外求的靈性自足。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-64","chapterId":"cai-gen-tan_ch-2","order":64,"canonicalText":"閑觀撲紙蠅，笑癡人自生障礙；靜覩競巢鵲，嘆傑士空逞英雄。","sentenceIds":["cai-gen-tan_ch-2_p-64_s-1","cai-gen-tan_ch-2_p-64_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"閒暇時觀看蒼蠅不斷撲打窗紙，不禁嘲笑那些愚癡的人總是作繭自縛、自找麻煩；靜靜地目睹喜鵲為了爭奪巢穴而互相爭鬥，不由得感嘆那些所謂的豪傑之士往往只是徒勞地賣弄自己的英雄氣概。","analysis":"【訓詁與名物】「撲紙蠅」指蒼蠅為尋找出路而不斷撞擊窗戶上的糊紙，比喻盲目無明、找不到正確方向的行為。「癡人」指不明事理、執迷不悟的人。「障礙」即阻礙與困境。「競巢鵲」指為了爭奪鳥巢而爭鬥的喜鵲。「傑士」指才能出眾的人或自命不凡的豪傑。「空逞」意謂徒勞地展現或賣弄。\\\\n【章法與結構】本段同樣採用對偶句式，「閑觀撲紙蠅」對「靜覩競巢鵲」，「笑癡人自生障礙」對「嘆傑士空逞英雄」。作者藉由對自然界微小事物的細膩觀察（蠅與鵲），引申到對人類社會百態的深刻反思（癡人與傑士），由物及人，情景交融，對比鮮明。\\\\n【思想與義理】這裡蘊含著清醒的避世與無為思想。蒼蠅撲紙盲目衝撞，正如同世間凡夫俗子因為貪執而給自己製造無數煩惱；喜鵲爭巢激烈廝殺，則諷刺了世上那些為了名利權位而爭權奪利的英雄豪傑，到頭來終究是一場空。作者藉此勸誡人們要看破世俗的爭鬥與執著，打破自我設置的藩籬，放下無謂的競爭與虛榮，追求精神上的大自在與大解脫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-65","chapterId":"cai-gen-tan_ch-2","order":65,"canonicalText":"看破有盡身軀，萬境之塵緣自息；悟入無壞境界，一輪之心月獨明。","sentenceIds":["cai-gen-tan_ch-2_p-65_s-1","cai-gen-tan_ch-2_p-65_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"只要能看透這副有生有滅的肉身不過是短暫的存在，面對世間萬種境遇的塵俗牽絆自然就會平息；只要能領悟並進入那種不生不滅的永恆境界，內心就像一輪皎潔的明月般孤高清澄。","analysis":"【訓詁與名物】「有盡身軀」指人的肉體生命是有限的、終將消亡的。「萬境」指世間的種種現象與遭遇。「塵緣」指與世俗萬物相互糾纏的緣分與牽絆。「無壞境界」指超越生死輪迴、不生不滅的永恆精神境界或佛家所說的涅槃境界。「心月」是佛教用語，將清淨無染的本心比喻為明月。「獨明」意為獨自光明、圓滿清澈。\\\\n【章法與結構】對聯式的結構十分嚴密，「看破有盡身軀」對應「悟入無壞境界」，「萬境之塵緣自息」對應「一輪之心月獨明」。上半句從「破」字著手，談如何放下對肉體的執著以息滅塵緣；下半句從「立」（悟入）字立意，談達到精神超越後內心的澄明。一破一立，相得益彰。\\\\n【思想與義理】此段文字深受佛教唯識與禪宗思想的影響。其核心在於「破執」與「明心」。人之所以有煩惱，是因為執著於這具終將腐朽的肉身，進而產生種種貪嗔癡。一旦看破肉身的虛幻，切斷與世俗名利的羈絆，就能擺脫煩惱的束縛。進一步悟道，便能達到精神的永恆與清淨，如同夜空中皎潔的明月，不為烏雲所蔽，展現出生命本真的澄澈與圓滿。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-66","chapterId":"cai-gen-tan_ch-2","order":66,"canonicalText":"土牀石枕冷家風，擁衾時魂夢亦爽；麥飯豆羹淡滋味，放箸處齒頰猶香。","sentenceIds":["cai-gen-tan_ch-2_p-66_s-1","cai-gen-tan_ch-2_p-66_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"睡著泥土砌的牀、枕著石頭做的枕頭，雖然是清冷樸素的家風，但蓋上被子時，連靈魂與夢境都感到無比清爽；喫著粗麥飯、喝著豆子湯，雖然是清淡簡約的滋味，但在放下筷子的時候，齒頰之間依然留有餘香。","analysis":"【主題與背景】本段弘揚了儒家安貧樂道（如孔子讚顏回「一簞食，一瓢飲」）與禪宗農禪並重、珍惜物力的清修生活。在物質生活極度簡陋的「土牀石枕」與「麥飯豆羹」中，作者卻體會到了精神上的「魂夢亦爽」與「齒頰猶香」。\\\\n【詞義與名物】這說明生命的幸福不在於感官的奢侈享受，而在於心靈無負擔的純淨與對樸實生活的真誠感知。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-67","chapterId":"cai-gen-tan_ch-2","order":67,"canonicalText":"談紛華而厭者，或見紛華而喜；語淡泊而欣者，或處淡泊而厭。須掃除濃淡之見，滅卻欣厭之情，纔可以忘紛華而甘淡泊也。","sentenceIds":["cai-gen-tan_ch-2_p-67_s-1","cai-gen-tan_ch-2_p-67_s-2","cai-gen-tan_ch-2_p-67_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"嘴上談論世俗繁華就表現出厭惡的人，有時親眼見到繁華的景象卻會心生歡喜；口中說到淡泊生活就顯得十分嚮往的人，有時真的身處淡泊的環境中卻會感到厭倦。因此，必須徹底清除心中對於濃烈與平淡的分別見解，消滅對於事物的歡喜與厭惡之情，如此才可以真正忘卻繁華的誘惑，並甘之如飴地安於淡泊的生活。","analysis":"【訓詁與名物】「紛華」指繁華喧鬧、富貴奢華的世俗生活。「語淡泊」意為談論清靜寡慾、簡單樸素的生活。「濃淡之見」指將事物區分為繁華（濃）與清苦（淡）的二元對立觀念。「欣厭之情」即歡喜與厭惡的主觀情緒。「甘」指甘心、安於。\\\\n【章法與結構】本段文字採用先破後立的論述結構。前兩句為第一層，以兩個假設的情境，揭示世人言行不一、內外矛盾的心理狀態；後兩句為第二層，提出解決之道，點明唯有超越二元對立，方能達到真正的境界。句式上錯落有致，富有邏輯思辨的張力。\\\\n【思想與義理】這段話探討了修心的深層次境界。許多人對繁華與淡泊的態度往往停留在表面，並非發自內心的體悟，因而容易出現言行不一的狀況。作者指出，真正的修養不在於刻意表現出對繁華的厭惡或對淡泊的喜愛，而是要徹底打破心中的分別心（濃淡之見）與執著情緒（欣厭之情）。只有當內心不再受外界環境的左右，達到無心、無求的境界時，才能真正做到在繁華中不迷失，在淡泊中得安寧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-68","chapterId":"cai-gen-tan_ch-2","order":68,"canonicalText":"「鳥驚心」「花濺淚」，懷此熱肝腸，如何領取得冷風月；「山寫照」「水傳神」，識吾真面目，方可擺脫得幻乾坤。富貴得一生寵榮，到死時反增了一個戀字，如負重擔；貧賤得一世清苦，到死時反脫了一個厭字，如釋重枷。人誠想念到此，當急回貪戀之首而猛舒愁苦之眉矣。","sentenceIds":["cai-gen-tan_ch-2_p-68_s-1","cai-gen-tan_ch-2_p-68_s-2","cai-gen-tan_ch-2_p-68_s-3","cai-gen-tan_ch-2_p-68_s-4","cai-gen-tan_ch-2_p-68_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"「感時花濺淚，恨別鳥驚心」，若心中懷著這樣過度執著、多愁善感的熾熱心腸，又如何能領略大自然清幽冷靜的風花雪月？「山川為我寫照，流水為我傳神」，唯有在自然山水中認清自己的本真面目，才可以徹底擺脫這個虛幻不實的塵世乾坤。富貴之人一生享受恩寵與榮耀，到了臨終時反而增加了一個「戀戀不捨」的執念，就像背負著沉重的負擔；貧賤之人一生經歷清貧與困苦，到了臨終時反而擺脫了一個「厭惡」的執念，就像解脫了沉重的枷鎖。人如果真的能深切想到這一點，就應當急忙回頭，不再貪戀虛名，並猛然舒展愁苦的眉頭。","analysis":"【主題與背景】此段是一篇極具文學色彩與哲理深度的警世之作。前半段借用杜甫《春望》的名句，指出若沉溺於人間情愛與得失的「熱肝腸」，便無法進入清涼無為的自然境界（冷風月）；而以山水為鏡，則能照見佛教的「本來面目」。\\\\n【詞義與名物】後半段通過富貴者臨死之「戀」與貧賤者臨死之「脫」的對比，揭示了名利對心靈的終極束縛（重擔與重枷）。\\\\n【思想與篇章】作者以此規勸世人看破得失，回頭是岸，舒展愁眉，回歸自然的無礙。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-69","chapterId":"cai-gen-tan_ch-2","order":69,"canonicalText":"人之有生也，如太倉之粒米，如灼目之電光，如懸崖之朽木，如逝海之巨波。知此者如何不悲？如何不樂？如何看他不破而懷貪生之慮？如何看他不重而貽虛生之羞？","sentenceIds":["cai-gen-tan_ch-2_p-69_s-1","cai-gen-tan_ch-2_p-69_s-2","cai-gen-tan_ch-2_p-69_s-3","cai-gen-tan_ch-2_p-69_s-4","cai-gen-tan_ch-2_p-69_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人短暫的一生，就像是巨大穀倉裡的一粒米般微小，像刺眼的閃電般轉瞬即逝，像懸崖邊的朽木般搖搖欲墜，又像流向大海的巨大波浪般一去不返。能夠明白這個道理的人，怎麼會不感到悲傷？又怎麼會不感到快樂呢？怎麼會看不透生命的短暫而心懷貪生怕死的憂慮？又怎麼會不看重生命的價值，而留下虛度光陰的羞悔呢？","analysis":"【訓詁與名物】\\\\n「太倉」即指古代國家的大穀倉，借指極其龐大的空間；「灼目」為刺眼，形容電光閃爍之烈與短促；「逝海」意謂江水奔流向海，象徵不可逆轉的時光；「貽」作遺留、留下解。「太倉之粒米」典出《莊子·秋水》：「計中國之在海內，不似稊米之在大倉乎？」極言人之渺小。\\\\n【章法與結構】\\\\n首句連用四個「如」字，構成排比，分別從空間的微小（粒米）、時間的短促（電光）、處境的危殆（朽木）、去勢的無回（巨波）四個維度，勾勒出人生的短暫與脆弱。後半段則以四個「如何」構成的反問句緊接，先將「悲」與「樂」對舉，再把「貪生」與「虛生」並陳，層層遞進，氣勢跌宕起伏。\\\\n【思想與義理】\\\\n此段文字體現了儒道釋交融的生命哲學。一方面，作者具有道家與佛家對生命短暫、渺小與無常的深刻體認，故言「看破」而不貪生；另一方面，又帶有儒家積極入世、珍視生命的擔當精神，強調不可「虛生」。人生雖短暫如朝露，但既不應恐懼死亡，也不可頹廢度日，而應在有限的年華中把握當下，活出生命的真實價值，達致悲喜交融而超然物外的豁達境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-70","chapterId":"cai-gen-tan_ch-2","order":70,"canonicalText":"鷸蚌相持，兔犬共斃，冷覷來令人猛氣全消；鷗鳧共浴，鹿豕同眠，閑觀去使我機心頓息。","sentenceIds":["cai-gen-tan_ch-2_p-70_s-1","cai-gen-tan_ch-2_p-70_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鷸與蚌互相鉗制僵持，兔子與獵狗雙雙精疲力竭而亡，冷眼看著這些世俗爭鬥，頓時讓人爭強好勝的勇猛之氣消散殆盡；海鷗與野鴨在水中共同沐浴，野鹿與野豬在山林中安然同眠，閒適地看著這幅和諧的景象，使我內心投機取巧的機巧之心頓時平息。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈應酬〉第 143 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「鷸蚌相持兔犬共斃冷覷來令人猛氣全消鷗鳧共……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「鷸」、「蚌」、「相」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-2_p-70）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-71","chapterId":"cai-gen-tan_ch-2","order":71,"canonicalText":"迷則樂境成苦海，如水凝為冰；悟則苦海為樂境，猶冰渙作水。可見苦樂無二境，迷悟非兩心，只在一轉念間耳。","sentenceIds":["cai-gen-tan_ch-2_p-71_s-1","cai-gen-tan_ch-2_p-71_s-2","cai-gen-tan_ch-2_p-71_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果心智迷惘，即使身處歡樂的境界也會變成痛苦的深淵，就像水凝結成冰一樣；如果心靈覺悟，即使身在痛苦的深淵也能化為歡樂的境界，如同冰融解成水一般。由此可知，痛苦與快樂本來就沒有截然不同的環境，迷惘與覺悟也不是兩種截然不同的心境，這一切的轉變，其實都只在人心的一念之間罷了。","analysis":"【訓詁與名物】\\\\n「迷」指執迷不悟、心生煩惱；「悟」指覺醒、通達真理；「苦海」為佛教語，比喻無邊無際的痛苦世界；「渙」指消散、融解，此處指冰化為水。「轉念」意謂念頭的轉換或思維角度的改變。水與冰在物理本質上是同一物質，作者藉此巧妙比喻心境的兩種狀態。\\\\n【章法與結構】\\\\n全段以對比與比喻為骨幹，前兩句將「迷」與「悟」、「樂境」與「苦海」相對仗，並以「水凝為冰」與「冰渙作水」這組自然現象作為生動的譬喻，句式整齊且具對稱美。最後以「可見」二字作結，總結出「苦樂無二境，迷悟非兩心」的哲理，並以「一轉念間」畫龍點睛，收束全篇。\\\\n【思想與義理】\\\\n本段深受禪宗與天台宗「一念三千」、「煩惱即菩提」思想的影響。指出外在的境遇（苦與樂）並非絕對，而是取決於內在心境（迷與悟）的投射。冰與水的本質相同，只是狀態不同，象徵著凡夫與覺者共享同一真心，差別僅在於是否執著。只要能夠轉化看待世事的觀念，放下執念，便能立刻從痛苦的深淵中解脫，化煩惱為智慧，展現出高度的唯心主義色彩與心靈自由。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-72","chapterId":"cai-gen-tan_ch-2","order":72,"canonicalText":"遍閱人情，始識疎狂之足貴；備嘗世味，方知淡泊之為真。","sentenceIds":["cai-gen-tan_ch-2_p-72_s-1","cai-gen-tan_ch-2_p-72_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"看盡了世間各種人情冷暖之後，才明白那種不拘小節、放蕩不羈的性格是多麼值得珍貴；充分嚐遍了社會上的酸甜苦辣之後，才會懂得清心寡慾、恬淡無爭才是最真實的人生境界。","analysis":"【訓詁與名物】\\\\n「遍閱」即全面經歷、看盡；「人情」指世俗的人際交往與世態炎涼；「疎狂」本指放蕩不羈、不拘禮法，此處引申為不受世俗規範束縛的率真本性；「備嘗」意為充分體驗；「世味」指人世間的種種滋味，包含榮辱得失；「淡泊」謂不追求名利，清虛恬靜。\\\\n【章法與結構】\\\\n此段為極為工整的對偶句。「遍閱人情」對「備嘗世味」，「始識疎狂之足貴」對「方知淡泊之為真」。兩句皆採用條件與結果的邏輯句式（「……始/方……」），透過工整的節奏，將人生歷練與心理體悟層層呼應，讀來朗朗上口，語氣中帶著經歷滄桑後的沉靜。\\\\n【思想與義理】\\\\n作者透過歷經世事後的反思，指出世俗禮法與功名利祿往往使人虛偽造作，唯有在看透世態炎涼後，才會發現保持本真的「疎狂」是極其難得的品質。而繁華落盡見真淳，追求濃烈的名利最終都會歸於虛無，只有退守「淡泊」，才能尋得心靈的安寧與生命的實相。這體現了道家返璞歸真、老莊崇尚自然的處世哲學，教導人在喧囂塵世中守住內心的清明與自在。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-2_p-73","chapterId":"cai-gen-tan_ch-2","order":73,"canonicalText":"地寬天高，尚覺鵬程之窄小；雲深松老，方知鶴夢之悠閒。","sentenceIds":["cai-gen-tan_ch-2_p-73_s-1","cai-gen-tan_ch-2_p-73_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在大地遼闊、天空高遠的境界中，依然會覺得鯤鵬展翅萬裡的前程其實有些狹隘侷促；唯有身處雲霧深鎖、古松蒼老的大自然裡，才能真正體會到仙鶴夢境般的清閒與自在。","analysis":"【主題與背景】此段對莊子《逍遙遊》中的「大鵬」意象進行了獨特的哲學重構。在莊子中，大鵬展翅九萬里是宏大志向的象徵。\\\\n【詞義與名物】然而本段作者指出，大鵬的「鵬程萬裏」依然需要依賴大風，且有著明確的目的與追求，因此在精神絕對自由的層面上仍嫌「窄小」。\\\\n【思想與篇章】相反地，無求無欲、安於「雲深松老」之中的「鶴夢」，代表了一種完全擺脫功名與志向束縛、與自然融為一體的純粹悠閒，這才是更高的無待之境。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"cai-gen-tan_ch-2_p-1_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-1","order":1,"canonicalText":"先達笑彈冠，休向侯門輕曳裾；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-1_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-1","order":2,"canonicalText":"相知猶按劍，莫從世路暗投珠。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-2_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-2","order":1,"canonicalText":"楊修之軀見殺於曹操，以露己之長也；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-2_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-2","order":2,"canonicalText":"韋誕之墓見伐於鐘繇，以祕己之美也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-2_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-2","order":3,"canonicalText":"故哲士多匿採以韜光，至人常遜美而公善。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-3_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-3","order":1,"canonicalText":"少年的人，不患其不奮迅，常患畚迅而成鹵莽，故當抑其躁心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-3_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-3","order":2,"canonicalText":"老成的人，不患其不持重，常患以持重而成退縮，故當振其惰氣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-4_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-4","order":1,"canonicalText":"望重縉紳，怎似寒微之頌德。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-4_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-4","order":2,"canonicalText":"朋來海宇，何如骨肉之孚心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-5_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-5","order":1,"canonicalText":"舌存常見齒亡，剛強終不勝柔弱；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-5_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-5","order":2,"canonicalText":"戶朽未聞樞蠹，偏執豈能及圓融。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-6_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-6","order":1,"canonicalText":"物莫大於天地日月，而子美雲：「日月籠中鳥，乾坤水上萍。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-6_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-6","order":2,"canonicalText":"」事莫大於揖遜徵誅，而康節雲：「唐虞揖遜三杯酒，湯武徵誅一局棋。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-6_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-6","order":3,"canonicalText":"」人能以此胸襟眼界吞吐六合，上下千古，事來如漚生大海，事去如影滅長空，自經綸萬變而不動一塵矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-7_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-7","order":1,"canonicalText":"君子好名，便起欺人之念；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-7_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-7","order":2,"canonicalText":"小人好名，猶懷畏人之心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-7_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-7","order":3,"canonicalText":"故人而皆好名，則開詐善之門。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-7_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-7","order":4,"canonicalText":"使人而不好名，則絕為善之路。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-7_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-7","order":5,"canonicalText":"此譏好名者，當嚴責君子，不當過求於小人也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-8_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-8","order":1,"canonicalText":"大惡多從柔處伏，哲士須防綿裏之針；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-8_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-8","order":2,"canonicalText":"深仇常自愛中來，達人宜遠刀頭之蜜。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-9_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-9","order":1,"canonicalText":"持身涉世，不可隨境而遷。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-9_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-9","order":2,"canonicalText":"須是大火流金而清風穆然，嚴霜殺物而和氣藹然，陰霾翳空而慧日朗然，洪濤倒海而砥柱屹然，方是宇宙內的真人品。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-9_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-9","order":3,"canonicalText":"愛是萬緣之根，當知割捨。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-9_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-9","order":4,"canonicalText":"識是眾欲之本，要力掃除。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-10_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-10","order":1,"canonicalText":"作人要脫俗，不可存一矯俗之心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-10_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-10","order":2,"canonicalText":"應世要隨時，不可起一趨時之念。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-11_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-11","order":1,"canonicalText":"寧有求全之毀，不可有過情之譽；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-11_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-11","order":2,"canonicalText":"寧有無妄之災，不可有非分之福。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-12_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-12","order":1,"canonicalText":"毀人者不美，而受人毀者遭一番訕謗便加一番修省，可釋回而增美；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-12_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-12","order":2,"canonicalText":"欺人者非福，而受人欺者遇一番橫逆便長一番器宇，可以轉禍而為福。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-13_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-13","order":1,"canonicalText":"夢裏懸金佩玉，事事逼真，睡去雖真覺後假；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-13_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-13","order":2,"canonicalText":"閒中演偈談元，言言酷似，說來雖是用時非。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-14_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-14","order":1,"canonicalText":"天欲禍人，必先以微福驕之，所以福來不必喜，要看他會受；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-14_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-14","order":2,"canonicalText":"天欲福人，必先以微禍儆之，所以禍來不必憂，要看他會救。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-15_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-15","order":1,"canonicalText":"榮與辱共蒂，厭辱何須求榮；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-15_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-15","order":2,"canonicalText":"生與死同根，貪生不必畏死。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-16_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-16","order":1,"canonicalText":"作人只是一味率真，蹤跡雖隱還顯；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-16_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-16","order":2,"canonicalText":"存心若有半毫未凈，事為雖公亦私。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-17_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-17","order":1,"canonicalText":"鷯佔一枝，反笑鵬心奢侈；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-17_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-17","order":2,"canonicalText":"兔營三窟，轉嗤鶴壘高危。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-17_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-17","order":3,"canonicalText":"智小者不可以謀大，趣卑者不可與談高。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-17_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-17","order":4,"canonicalText":"信然矣！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-18_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-18","order":1,"canonicalText":"貧賤驕人，雖涉虛憍，還有幾分俠氣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-18_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-18","order":2,"canonicalText":"英雄欺世，縱似揮霍，全沒半點真心。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-18_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-18","order":3,"canonicalText":"糟糠不為彘肥，何事偏貪鈎下餌；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-18_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-18","order":4,"canonicalText":"錦綺豈因犧貴，誰人能解籠中囮。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-19_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-19","order":1,"canonicalText":"琴書詩畫，達士以之養性靈，而庸夫徒賞其跡像；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-19_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-19","order":2,"canonicalText":"山川雲物，高人以之助學識，而俗子徒玩其光華。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-19_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-19","order":3,"canonicalText":"可見事物無定品，隨人識見以為高下。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-19_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-19","order":4,"canonicalText":"故讀書窮理，要以識趣為先。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-20_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-20","order":1,"canonicalText":"美女不尚鉛華，似疏梅之映淡月；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-20_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-20","order":2,"canonicalText":"禪師不落空寂，若碧沼之吐青蓮。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-21_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-21","order":1,"canonicalText":"廉官多無後，以其太清也；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-21_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-21","order":2,"canonicalText":"癡人每多福，以其近厚也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-21_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-21","order":3,"canonicalText":"故君子雖重廉介，不可無含垢納污之雅量。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-21_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-21","order":4,"canonicalText":"雖戒癡頑，亦不必有察淵洗垢之精明。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-22_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-22","order":1,"canonicalText":"密則神氣拘逼，疏則天真爛漫，此豈獨詩文之工拙從此分哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-22_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-22","order":2,"canonicalText":"吾見周密之人純用機巧，疏狂之士獨任性真，人心之生死亦於此判也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-23_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-23","order":1,"canonicalText":"翠筱傲嚴霜，節縱孤高，無傷沖雅；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-23_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-23","order":2,"canonicalText":"紅蕖媚秋水，色雖艷麗，何損清修。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-24_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-24","order":1,"canonicalText":"貧賤所難，不難在砥節，而難在用情；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-24_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-24","order":2,"canonicalText":"富貴所難，不難在推恩，而難在好禮。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-25_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-25","order":1,"canonicalText":"簪纓之士，常不及孤寒之子可以抗節致忠；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-25_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-25","order":2,"canonicalText":"廟堂之士，常不及山野之夫可以料事燭理。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-25_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-25","order":3,"canonicalText":"何也？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-25_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-25","order":4,"canonicalText":"彼以濃艷損志，此以淡泊全真也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-26_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-26","order":1,"canonicalText":"榮寵傍邊辱等待，不必揚揚；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-26_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-26","order":2,"canonicalText":"困窮背後福跟隨，何須慼慼。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-27_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-27","order":1,"canonicalText":"古人閑適處，今人卻忙過了一生；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-27_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-27","order":2,"canonicalText":"古人實受處，今人又虛度了一世。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-27_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-27","order":3,"canonicalText":"總是耽空逐妄，看個色身不破，認個法身不真耳。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-28_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-28","order":1,"canonicalText":"芝草無根醴無源，志士當勇奮翼；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-28_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-28","order":2,"canonicalText":"彩雲易散琉璃脆，達人當早回頭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-29_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-29","order":1,"canonicalText":"少壯者，事事當用意而意反輕，徒汛汛作水中鳧而已，何以振雲霄之翮？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-29_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-29","order":2,"canonicalText":"衰老者，事事宜忘情而情反重，徒碌碌為轅下駒而已，何以脫韁鎖之身？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-30_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-30","order":1,"canonicalText":"帆只揚五分，船便安。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-30_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-30","order":2,"canonicalText":"水只注五分，器便穩。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-30_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-30","order":3,"canonicalText":"如韓信以勇備震主被擒，陸機以才名冠世見殺，霍光敗於權勢逼君，石崇死於財賦敵國，皆以十分取敗者也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-30_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-30","order":4,"canonicalText":"康節雲：「飲酒莫教成酩酊，看花慎勿至離披。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-30_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-30","order":5,"canonicalText":"」旨哉言乎！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-31_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-31","order":1,"canonicalText":"附勢者如寄生依木，木伐而寄生亦枯；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-31_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-31","order":2,"canonicalText":"竊利者如𧕍虰盜人，人死而𧕍虰亦滅。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-31_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-31","order":3,"canonicalText":"始以勢利害人，終以勢利自斃。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-31_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-31","order":4,"canonicalText":"勢利之為害也，如是夫！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-32_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-32","order":1,"canonicalText":"醉後添杯不如渺渺看雲，興尖納履不如悠悠觀水。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-33_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-33","order":1,"canonicalText":"鶴立雞羣，可謂超然無侶矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-33_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-33","order":2,"canonicalText":"然進而觀於大海之鵬，則眇然自小。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-33_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-33","order":3,"canonicalText":"又進而求之九霄之鳳，則巍乎莫及。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-33_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-33","order":4,"canonicalText":"所以至人常若無若虛，而盛德多不矜不伐也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-34_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-34","order":1,"canonicalText":"極思辱者，每自冤恨；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-34_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-34","order":2,"canonicalText":"極喜歡者，每自遺悔。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-35_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-35","order":1,"canonicalText":"蛾撲火，火焦蛾，莫謂禍生無本；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-35_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-35","order":2,"canonicalText":"果種花，花結果，須知福至有因。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-36_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-36","order":1,"canonicalText":"車爭險道，馬騁先鞭，到敗處未免噬臍；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-36_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-36","order":2,"canonicalText":"粟喜堆山，金誇過鬥，臨行時還是空手。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-37_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-37","order":1,"canonicalText":"花逞春光，一番雨、一番風，催歸塵土；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-37_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-37","order":2,"canonicalText":"竹堅雅操，幾朝霜、幾朝雪，傲就瑯玕。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-38_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-38","order":1,"canonicalText":"富貴是無情之物，看得他重，他害你越大；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-38_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-38","order":2,"canonicalText":"貧賤是耐久之交，處得他好，他益你深。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-38_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-38","order":3,"canonicalText":"故貪商於而戀金谷者，竟被一時之顯戮；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-38_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-38","order":4,"canonicalText":"樂簞瓢而甘敝縕者，終享千載之令名。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-39_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-39","order":1,"canonicalText":"鴿惡鈴而高飛，不知斂翼而鈴自息；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-39_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-39","order":2,"canonicalText":"人惡影而疾走，不知處陰而影自滅。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-39_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-39","order":3,"canonicalText":"故愚夫徒疾走高飛，而平地反為苦海；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-39_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-39","order":4,"canonicalText":"達士知處陰斂翼，而巉巖亦是坦途。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-40_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-40","order":1,"canonicalText":"秋蟲春鳥共暢天機，何必浪生悲喜；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-40_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-40","order":2,"canonicalText":"老樹新花同含生意，胡為妄別媸妍。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-41_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-41","order":1,"canonicalText":"多栽桃李少栽荊，便是開條福路；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-41_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-41","order":2,"canonicalText":"不積詩書偏積玉，還如築個禍基。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-42_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-42","order":1,"canonicalText":"萬境一轍原無地，著個窮通；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-42_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-42","order":2,"canonicalText":"萬物一體原無處，分個彼我。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-42_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-42","order":3,"canonicalText":"世人迷真逐妄，乃向坦途上自設一坷坎，從空洞中自築一藩籬。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-42_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-42","order":4,"canonicalText":"良足慨哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-43_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-43","order":1,"canonicalText":"大聰明的人，小事必朦朧；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-43_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-43","order":2,"canonicalText":"大懵懂的人，小事必伺察。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-43_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-43","order":3,"canonicalText":"蓋伺察乃懵懂之根，而朦朧正聰明之窟也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-44_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-44","order":1,"canonicalText":"大烈鴻猷，常出悠閑鎮定之士，不必忙忙；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-44_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-44","order":2,"canonicalText":"休徵景福，多集寬洪長厚之家，何須瑣瑣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-45_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-45","order":1,"canonicalText":"貧士肯濟人，纔是性天中惠澤；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-45_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-45","order":2,"canonicalText":"鬧場能學道，方為心地上工夫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-46_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-46","order":1,"canonicalText":"人生只為欲字所累，便如馬如牛，聽人羈絡；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-46_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-46","order":2,"canonicalText":"為鷹為犬，任物鞭笞。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-46_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-46","order":3,"canonicalText":"若果一念清明，淡然無欲，天地也不能轉動我，鬼神也不能役使我，況一切區區事物乎！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-47_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-47","order":1,"canonicalText":"貪得者身富而心貧，知足者身貧而心富；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-47_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-47","order":2,"canonicalText":"居高者形逸而神勞，處下者形勞而神逸。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-47_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-47","order":3,"canonicalText":"孰得孰失，孰幻孰真，達人當自辨之。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-48_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-48","order":1,"canonicalText":"眾人以順境為樂，而君子樂自逆境中來；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-48_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-48","order":2,"canonicalText":"眾人以拂意為憂，而君子憂從快意處起。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-48_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-48","order":3,"canonicalText":"蓋眾人憂樂以情，而君子憂樂以理也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-49_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-49","order":1,"canonicalText":"謝豹覆面，猶知自愧；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-49_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-49","order":2,"canonicalText":"唐鼠易腸，猶知自悔。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-49_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-49","order":3,"canonicalText":"蓋愧悔二字，乃吾人去惡遷善之門，起死回生之路也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-49_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-49","order":4,"canonicalText":"人生若無此念頭，便是既死之寒灰，已枯之槁木矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-49_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-49","order":5,"canonicalText":"何處討些生理？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-50_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-50","order":1,"canonicalText":"異寶奇琛，俱是必爭之器；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-50_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-50","order":2,"canonicalText":"瑰節奇行，多冒不祥之名。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-50_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-50","order":3,"canonicalText":"總不若尋常歷履易簡行藏，可以完天地渾噩之真，享民物和平之福。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-51_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-51","order":1,"canonicalText":"福善不在杳冥，即在食息起居處牖其衷；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-51_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-51","order":2,"canonicalText":"禍淫不在幽渺，即在動靜語默間奪其魄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-51_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-51","order":3,"canonicalText":"可見人之精爽常通於天，於之威命即寓於人，天人豈相遠哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-52_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-52","order":1,"canonicalText":"晝閑人寂，聽數聲鳥語悠揚，不覺耳根盡徹；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-52_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-52","order":2,"canonicalText":"夜靜天高，看一片雲光舒捲，頓令眼界俱空。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-53_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-53","order":1,"canonicalText":"世事如棋局，不著得纔是高手；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-53_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-53","order":2,"canonicalText":"人生似瓦盆，打破了方見真空。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-54_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-54","order":1,"canonicalText":"龍可豢非真龍，虎可搏非真虎，故爵祿可餌榮進之輩，必不可籠淡然無欲之人；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-54_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-54","order":2,"canonicalText":"鼎鑊可及寵利之流，必不可加飄然遠引之士。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-55_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-55","order":1,"canonicalText":"一場閑富貴，狠狠爭來，雖得還是失；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-55_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-55","order":2,"canonicalText":"百歲好光陰，忙忙過了，縱壽亦為殀。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-56_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-56","order":1,"canonicalText":"高車嫌地僻，不如魚鳥解親人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-56_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-56","order":2,"canonicalText":"駟馬喜門高，怎似鶯花能避俗。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-57_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-57","order":1,"canonicalText":"紅燭燒殘，萬念自然厭冷；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-57_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-57","order":2,"canonicalText":"黃梁夢破，一身亦似雲浮。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-58_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-58","order":1,"canonicalText":"千載奇逢，無如好書良友；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-58_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-58","order":2,"canonicalText":"一生清福，只在椀茗爐煙。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-59_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-59","order":1,"canonicalText":"蓬茅下誦詩讀書，日日與聖賢晤語，誰雲貧是病？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-59_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-59","order":2,"canonicalText":"樽壘邊幕天席地，時時共造化氤氳，孰謂醉非禪？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-59_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-59","order":3,"canonicalText":"興來醉倒落花前，天地即為衾枕。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-59_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-59","order":4,"canonicalText":"機息坐忘盤石上，古今盡屬蜉蝣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-60_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-60","order":1,"canonicalText":"昂藏老鶴雖飢，飲啄猶閒，肯同雞鶩之營營而競食？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-60_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-60","order":2,"canonicalText":"偃蹇寒松縱老，豐標自在，豈似桃李之灼灼而爭妍！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-61_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-61","order":1,"canonicalText":"吾人適志於花柳爛熳之時，得趣於笙歌騰沸之處，乃是造化之幻境，人心之蕩念也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-61_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-61","order":2,"canonicalText":"須從木落草枯之後，向聲希味淡之中，覓得一些消息，纔是乾坤的橐籥，人物的根宗。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-62_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-62","order":1,"canonicalText":"靜處觀人事，即伊呂之勳庸、夷齊之節義，無非大海浮漚；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-62_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-62","order":2,"canonicalText":"閒中玩物情，雖木石之偏枯、鹿豕之頑蠢，總是吾性真如。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-63_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-63","order":1,"canonicalText":"花開花謝春不管，拂意事休對人言；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-63_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-63","order":2,"canonicalText":"水煖水寒魚自知，會心處還期獨賞。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-64_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-64","order":1,"canonicalText":"閑觀撲紙蠅，笑癡人自生障礙；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-64_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-64","order":2,"canonicalText":"靜覩競巢鵲，嘆傑士空逞英雄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-65_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-65","order":1,"canonicalText":"看破有盡身軀，萬境之塵緣自息；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-65_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-65","order":2,"canonicalText":"悟入無壞境界，一輪之心月獨明。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-66_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-66","order":1,"canonicalText":"土牀石枕冷家風，擁衾時魂夢亦爽；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-66_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-66","order":2,"canonicalText":"麥飯豆羹淡滋味，放箸處齒頰猶香。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-67_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-67","order":1,"canonicalText":"談紛華而厭者，或見紛華而喜；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-67_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-67","order":2,"canonicalText":"語淡泊而欣者，或處淡泊而厭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-67_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-67","order":3,"canonicalText":"須掃除濃淡之見，滅卻欣厭之情，纔可以忘紛華而甘淡泊也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-68_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-68","order":1,"canonicalText":"「鳥驚心」「花濺淚」，懷此熱肝腸，如何領取得冷風月；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-68_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-68","order":2,"canonicalText":"「山寫照」「水傳神」，識吾真面目，方可擺脫得幻乾坤。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-68_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-68","order":3,"canonicalText":"富貴得一生寵榮，到死時反增了一個戀字，如負重擔；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-68_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-68","order":4,"canonicalText":"貧賤得一世清苦，到死時反脫了一個厭字，如釋重枷。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-68_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-68","order":5,"canonicalText":"人誠想念到此，當急回貪戀之首而猛舒愁苦之眉矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-69_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-69","order":1,"canonicalText":"人之有生也，如太倉之粒米，如灼目之電光，如懸崖之朽木，如逝海之巨波。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-69_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-69","order":2,"canonicalText":"知此者如何不悲？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-69_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-69","order":3,"canonicalText":"如何不樂？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-69_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-69","order":4,"canonicalText":"如何看他不破而懷貪生之慮？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-69_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-69","order":5,"canonicalText":"如何看他不重而貽虛生之羞？","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-70_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-70","order":1,"canonicalText":"鷸蚌相持，兔犬共斃，冷覷來令人猛氣全消；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-70_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-70","order":2,"canonicalText":"鷗鳧共浴，鹿豕同眠，閑觀去使我機心頓息。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-71_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-71","order":1,"canonicalText":"迷則樂境成苦海，如水凝為冰；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-71_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-71","order":2,"canonicalText":"悟則苦海為樂境，猶冰渙作水。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-71_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-71","order":3,"canonicalText":"可見苦樂無二境，迷悟非兩心，只在一轉念間耳。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-72_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-72","order":1,"canonicalText":"遍閱人情，始識疎狂之足貴；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-72_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-72","order":2,"canonicalText":"備嘗世味，方知淡泊之為真。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-73_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-73","order":1,"canonicalText":"地寬天高，尚覺鵬程之窄小；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-2_p-73_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-2","passageId":"cai-gen-tan_ch-2_p-73","order":2,"canonicalText":"雲深松老，方知鶴夢之悠閒。","chunks":[],"tags":[]}]}');export{a as default};
